values
('vs-001', 'vital_sign', 'heart-rate', 'zh-TW', 'published', '{"id":"vs-001","type":"vital_sign","slug":"heart-rate","locale":"zh-TW","title":"心跳率 (HR) 正常範圍","subtitle":"Heart Rate","aliases":["HR","心率","脈搏","heart rate","心跳次數"],"shortSummary":"安靜清醒狀態下心跳率參考範圍，依年齡差異呈現；危急閾值以一般參考為主，通報依單位規範。","targetUser":["nursing_student"],"clinicalSetting":["ward","er","icu","pediatric","opd"],"ageScope":["neonate","infant","child","adolescent","adult","elderly"],"priority":"high","tags":["生命徵象","cardiovascular"],"categories":["生命徵象/心跳"],"caution":[{"level":"info","message":"正常範圍因情境（運動、發燒、孕期）而異；是否屬「異常」與通報時機請依單位規範與帶教老師指示。"}],"bodySections":[{"key":"context_modifiers","label":"常見情境修正","layout":"kv_table","collapsedByDefault":false,"displayHint":"expanded","content":[{"key":"發燒","value":"體溫每升 1°C，心跳可能上升約 10 bpm。"},{"key":"運動 / 哭鬧後","value":"短暫升高至 150–180 bpm 屬常見，建議休息 5 分鐘後重測。"},{"key":"甲狀腺功能異常","value":"甲亢偏快、甲低偏慢；以實驗室數值與臨床表現綜合判讀。"}]},{"key":"measurement_tips","label":"量測小提示","layout":"bullet","collapsedByDefault":false,"displayHint":"expanded","content":["安靜清醒狀態下量測 1 分鐘最準確，避免運動後立即量測。","節律不規則時務必量整 1 分鐘並描述節律型態。","兒童哭鬧時不易取得真實基準，可於睡眠或安撫後再量。"]}],"quickActions":[],"references":[{"citation":"一般護理基礎教科書（範例條目）","sourceType":"textbook","sourceLang":"zh-TW"}],"review":{"version":"1.0.0","authoredBy":["seed"],"reviewedBy":[],"nextReviewDue":"2027-01-01","approvalScopes":["clinical_accuracy","language"]},"status":"published","createdAt":"2026-01-01T00:00:00Z","updatedAt":"2026-04-01T00:00:00Z","searchKeywords":["HR","心率","脈搏","bpm"],"parameter":"hr","unit":"bpm","byAgeTable":[{"ageLabel":"新生兒 (0–28 天)","ageMinDays":0,"ageMaxDays":28,"normalMin":100,"normalMax":160,"awakeOnly":true},{"ageLabel":"嬰兒 (1 個月–1 歲)","ageMinDays":29,"ageMaxDays":365,"normalMin":90,"normalMax":150},{"ageLabel":"幼兒 (1–3 歲)","ageMinDays":366,"ageMaxDays":1095,"normalMin":80,"normalMax":130},{"ageLabel":"兒童 (3–12 歲)","ageMinDays":1096,"ageMaxDays":4380,"normalMin":70,"normalMax":110},{"ageLabel":"青少年 (12–18 歲)","ageMinDays":4381,"ageMaxDays":6570,"normalMin":60,"normalMax":100},{"ageLabel":"成人 (≥18 歲)","ageMinDays":6571,"ageMaxDays":43800,"normalMin":60,"normalMax":100}],"criticalValues":{"low":50,"high":130,"note":"上述為一般參考閾值；是否屬危急值及通報時機請依各單位通報規範與臨床判斷。"},"measurementTips":["安靜狀態下量整 1 分鐘最準確。","節律不規則時必須量整 1 分鐘。"]}'::jsonb),
('vs-002', 'vital_sign', 'body-temperature', 'zh-TW', 'published', '{"id":"vs-002","type":"vital_sign","slug":"body-temperature","locale":"zh-TW","title":"體溫正常範圍","subtitle":"Body Temperature","aliases":["Temp","BT","體溫","temperature","發燒"],"shortSummary":"依量測部位差異呈現的成人體溫參考範圍；發燒之定義與通報依單位規範。","targetUser":["nursing_student"],"clinicalSetting":["ward","er","icu","pediatric","opd","ltc"],"ageScope":["neonate","infant","child","adolescent","adult","elderly"],"priority":"high","tags":["生命徵象","體溫"],"categories":["生命徵象/體溫"],"caution":[{"level":"info","message":"不同量測部位（口溫、腋溫、肛溫、耳溫、額溫）正常範圍略有差異，需依本院使用儀器之參考範圍為準。"}],"bodySections":[{"key":"by_route","label":"依量測部位參考範圍","layout":"kv_table","collapsedByDefault":false,"displayHint":"front","content":[{"key":"口溫 Oral","value":"36.0–37.4 °C"},{"key":"腋溫 Axillary","value":"比口溫低約 0.5 °C"},{"key":"肛溫 Rectal","value":"比口溫高約 0.5 °C"},{"key":"耳溫 Tympanic","value":"接近核心體溫，需注意操作技術"},{"key":"額溫 Temporal","value":"受環境影響大，作為初步篩檢"}]},{"key":"tips","label":"量測注意事項","layout":"bullet","collapsedByDefault":false,"displayHint":"expanded","content":["剛飲熱 / 冷飲料後 15–30 分鐘內避免量口溫。","腋溫需擦乾汗液並夾穩 5 分鐘以上（依儀器規範）。","高熱、低體溫應交叉確認量測部位與儀器準確度。"]}],"quickActions":[],"references":[{"citation":"一般護理基礎教科書（範例條目）","sourceType":"textbook","sourceLang":"zh-TW"}],"review":{"version":"1.0.0","authoredBy":["seed"],"reviewedBy":[],"nextReviewDue":"2027-01-01","approvalScopes":["clinical_accuracy","language"]},"status":"published","createdAt":"2026-01-01T00:00:00Z","updatedAt":"2026-04-01T00:00:00Z","searchKeywords":["BT","Temp","發燒","fever","hyperthermia"],"parameter":"temperature","unit":"°C","byAgeTable":[{"ageLabel":"全年齡（口溫參考）","ageMinDays":0,"ageMaxDays":43800,"normalMin":36,"normalMax":37.4}],"criticalValues":{"low":35,"high":39.5,"note":"低於 35°C 或高於 39.5°C 之處置與通報，請依各單位規範及醫療團隊判斷。"},"measurementTips":["同一病人請固定使用同一部位以利趨勢比較。","高熱兒童加強觀察活力、囪門、皮膚溫度與意識狀態變化。"]}'::jsonb),
('vs-003', 'vital_sign', 'respiratory-rate', 'zh-TW', 'published', '{"id":"vs-003","type":"vital_sign","slug":"respiratory-rate","locale":"zh-TW","title":"呼吸次數 (RR) 正常範圍","subtitle":"Respiratory Rate","aliases":["RR","呼吸","respiratory rate","呼吸次數","breath rate"],"shortSummary":"依年齡的呼吸次數參考範圍；觀察呼吸型態與費力程度同樣重要。","targetUser":["nursing_student"],"clinicalSetting":["ward","er","icu","pediatric"],"ageScope":["neonate","infant","child","adolescent","adult","elderly"],"priority":"high","tags":["生命徵象","respiratory"],"categories":["生命徵象/呼吸"],"caution":[{"level":"info","message":"呼吸次數加上呼吸型態（深淺、費力、輔助肌使用）一起判讀才完整。"}],"bodySections":[{"key":"patterns","label":"需要關注的呼吸型態","layout":"bullet","collapsedByDefault":false,"displayHint":"expanded","content":["使用輔助肌、鼻翼搧動、胸骨上凹陷（兒童重要徵象）。","呼吸暫停、Cheyne-Stokes、Kussmaul 型態。","伴隨 SpO2 下降或意識變化 → 依規範回報。"]}],"quickActions":[],"references":[{"citation":"一般護理基礎教科書（範例條目）","sourceType":"textbook","sourceLang":"zh-TW"}],"review":{"version":"1.0.0","authoredBy":["seed"],"reviewedBy":[],"nextReviewDue":"2027-01-01","approvalScopes":["clinical_accuracy"]},"status":"published","createdAt":"2026-01-01T00:00:00Z","updatedAt":"2026-04-01T00:00:00Z","searchKeywords":["RR","呼吸次數","breath rate"],"parameter":"rr","unit":"次/分","byAgeTable":[{"ageLabel":"新生兒","ageMinDays":0,"ageMaxDays":28,"normalMin":30,"normalMax":60},{"ageLabel":"嬰兒","ageMinDays":29,"ageMaxDays":365,"normalMin":25,"normalMax":50},{"ageLabel":"幼兒","ageMinDays":366,"ageMaxDays":1095,"normalMin":20,"normalMax":40},{"ageLabel":"兒童","ageMinDays":1096,"ageMaxDays":4380,"normalMin":18,"normalMax":30},{"ageLabel":"青少年","ageMinDays":4381,"ageMaxDays":6570,"normalMin":12,"normalMax":20},{"ageLabel":"成人","ageMinDays":6571,"ageMaxDays":43800,"normalMin":12,"normalMax":20}],"criticalValues":{"low":8,"high":30,"note":"是否屬危急值與通報，請依各單位通報規範與臨床判斷。"},"measurementTips":["量測時避免讓病人察覺，否則型態會改變；可在量脈搏時延伸觀察。","兒童因哭鬧 / 餵食而短暫升高，安撫後重測。"]}'::jsonb),
('vs-004', 'vital_sign', 'systolic-blood-pressure', 'zh-TW', 'published', '{"id":"vs-004","type":"vital_sign","slug":"systolic-blood-pressure","locale":"zh-TW","title":"收縮壓 (SBP) 參考範圍","subtitle":"Systolic Blood Pressure","aliases":["SBP","收縮壓","systolic","BP"],"shortSummary":"成人與老年收縮壓參考範圍；高血壓與低血壓的閾值依指引與情境而異。","targetUser":["nursing_student"],"clinicalSetting":["ward","opd","er","icu"],"ageScope":["adult","elderly"],"priority":"high","tags":["生命徵象","cardiovascular"],"categories":["生命徵象/血壓"],"caution":[{"level":"info","message":"單一測值不足以下結論；以多次趨勢與用藥前後比較較具臨床意義。"}],"bodySections":[{"key":"cuff_size","label":"量測注意","layout":"bullet","collapsedByDefault":false,"displayHint":"expanded","content":["使用合適尺寸的壓脈帶；過小高估、過大低估。","坐姿、雙腳著地、休息 5 分鐘後再量；手臂位於心臟高度。","初次量測雙臂以利後續比較。"]}],"quickActions":[],"references":[{"citation":"一般護理基礎教科書（範例條目）","sourceType":"textbook","sourceLang":"zh-TW"}],"review":{"version":"1.0.0","authoredBy":["seed"],"reviewedBy":[],"nextReviewDue":"2027-01-01","approvalScopes":["clinical_accuracy"]},"status":"published","createdAt":"2026-01-01T00:00:00Z","updatedAt":"2026-04-01T00:00:00Z","searchKeywords":["SBP","血壓","blood pressure"],"parameter":"sbp","unit":"mmHg","byAgeTable":[{"ageLabel":"成人（一般參考）","ageMinDays":6571,"ageMaxDays":43800,"normalMin":90,"normalMax":130}],"criticalValues":{"low":90,"high":180,"note":"上述為一般參考；高 / 低血壓之臨床意義與通報依單位規範與臨床判斷。"}}'::jsonb),
('drug-acetaminophen', 'drug', 'acetaminophen', 'zh-TW', 'published', '{"id":"drug-acetaminophen","type":"drug","slug":"acetaminophen","locale":"zh-TW","title":"Acetaminophen 乙醯胺酚","subtitle":"解熱鎮痛 — 兒童退燒首選","aliases":["Acetaminophen","Paracetamol","普拿疼","Panadol","Scanol","Tinten","安佳熱"],"shortSummary":"中樞作用解熱鎮痛劑；劑量上限與肝功能風險為主要安全焦點，兒童 3 個月以下唯一可用退燒藥。","targetUser":["nursing_student"],"clinicalSetting":["ward","er","opd","pediatric","home"],"ageScope":["neonate","infant","child","adolescent","adult","elderly","pregnant"],"priority":"high","tags":["解熱鎮痛","基本","pediatric"],"categories":["藥物/解熱鎮痛"],"caution":[{"level":"critical","message":"本卡為學習與雙重核對用；劑量、頻次以最新醫囑為準。注意 24 小時總劑量上限與肝功能風險。"},{"level":"warning","scope":"hepatic","message":"肝功能不全者每日不超過 2 g；與團隊確認個別劑量。"}],"redFlags":[{"trigger":"24 小時內已使用含 acetaminophen 成分的複方藥品（感冒藥、複方止痛藥）","actionHint":"考慮回報並重新評估總劑量，依單位規範跟進。"}],"bodySections":[{"key":"indications","label":"常見適應症","layout":"bullet","collapsedByDefault":false,"displayHint":"front","content":["發燒（兒童 ≥ 38.5°C）","輕至中度疼痛：頭痛、肌肉痠痛、術後疼痛","經痛"]},{"key":"nursing_focus","label":"護理觀察重點","layout":"bullet","collapsedByDefault":false,"displayHint":"front","content":["給藥前評估疼痛分數與體溫；給藥後 30–60 分鐘評估退燒成效。","監測 24 小時總劑量，注意複方感冒藥是否含相同成分。","長期 / 大量使用者監測 ALT / AST。","過量解毒劑為 N-acetylcysteine (NAC)。"]}],"quickActions":[],"references":[{"citation":"常用藥物資料庫（範例條目）","sourceType":"drug_database","sourceLang":"zh-TW"}],"review":{"version":"1.0.0","authoredBy":["seed"],"reviewedBy":[],"nextReviewDue":"2027-01-01","approvalScopes":["clinical_accuracy","safety_disclaimer"]},"status":"published","createdAt":"2026-05-11T00:00:00Z","updatedAt":"2026-05-11T00:00:00Z","searchKeywords":["普拿疼","acetaminophen","paracetamol","退燒","panadol","tinten"],"genericName":"Acetaminophen / Paracetamol","brandNames":["Panadol","普拿疼","Tinten 安佳熱","Scanol","Tempra"],"drugClass":["解熱鎮痛劑（非 NSAID）"],"highAlert":false,"indications":["輕至中度疼痛","發燒","經痛"],"contraindications":["對成分過敏","嚴重肝功能不全"],"routes":["po","pr","iv"],"doseReference":[{"population":"成人","route":"po","rangeText":"500–1000 mg 每 4–6 小時，24h 總劑量 ≤ 4 g（多數指引建議 ≤ 3 g 較安全）。","note":"僅供雙重核對；劑量以最新醫囑為準。","sourceRefIdx":0},{"population":"兒童（首選退燒）","route":"po","rangeText":"10–15 mg/kg/dose 每 4–6 小時，24h 總劑量 ≤ 75 mg/kg 且 ≤ 4 g。3 個月以下嬰兒首選退燒藥。","note":"兒科劑量請與處方對照。","sourceRefIdx":0}],"onsetPeakDuration":{"onset":"30 分鐘","peak":"1 小時","duration":"4–6 小時"},"adverseEffects":{"common":["一般耐受性佳"],"serious":["過量導致肝毒性","少見過敏反應"]},"monitoring":[{"parameter":"24 小時總劑量","trigger":"使用複方藥品或多次給藥時","actionHint":"與處方核對總劑量，避免無意中超量。"},{"parameter":"ALT / AST","trigger":"長期 / 大量使用","actionHint":"依單位規範頻次抽血。"}],"nursingConsiderations":["提醒病人勿同時自行使用含相同成分之感冒藥。","空腹或飯後皆可服用。","兒童體溫 < 38.5°C 不一定要給藥；可先物理降溫並補充水分。"],"interactionsBrief":["Warfarin：長期使用可能增加 INR。","酒精：增加肝毒性風險。"],"appearance":"錠劑、糖漿、栓劑、IV 注射等多種劑型。"}'::jsonb),
('drug-ibuprofen', 'drug', 'ibuprofen', 'zh-TW', 'published', '{"id":"drug-ibuprofen","type":"drug","slug":"ibuprofen","locale":"zh-TW","title":"Ibuprofen 布洛芬","subtitle":"NSAID — 抗發炎止痛退燒","aliases":["Ibuprofen","Brufen","Motrin","Advil","依普芬"],"shortSummary":"非類固醇抗發炎藥；具止痛退燒抗炎效果，需注意腸胃道、腎臟與出血風險。","targetUser":["nursing_student"],"clinicalSetting":["ward","opd","home","pediatric"],"ageScope":["infant","child","adolescent","adult","elderly"],"priority":"high","tags":["NSAID","解熱鎮痛"],"categories":["藥物/NSAID"],"caution":[{"level":"warning","message":"本卡為學習與雙重核對用；劑量、頻次以最新醫囑為準。"},{"level":"warning","scope":"pediatric","message":"< 6 個月嬰兒、脫水、水痘、登革熱避免使用（Reye 症候群、出血風險）。"}],"bodySections":[{"key":"indications","label":"常見適應症","layout":"bullet","collapsedByDefault":false,"displayHint":"front","content":["關節炎、肌肉痠痛","經痛","輕至中度疼痛、發燒","中耳炎、咽喉炎輔助"]},{"key":"nursing_focus","label":"護理觀察重點","layout":"bullet","collapsedByDefault":false,"displayHint":"front","content":["飯後服用以減少胃刺激。","可與 Acetaminophen 交替使用退頑固型發燒（須分開記錄時間）。","避免與其他 NSAIDs 併用。"]}],"quickActions":[],"references":[{"citation":"常用藥物資料庫（範例條目）","sourceType":"drug_database","sourceLang":"zh-TW"}],"review":{"version":"1.0.0","authoredBy":["seed"],"reviewedBy":[],"nextReviewDue":"2027-01-01","approvalScopes":["clinical_accuracy","safety_disclaimer"]},"status":"published","createdAt":"2026-05-11T00:00:00Z","updatedAt":"2026-05-11T00:00:00Z","searchKeywords":["布洛芬","ibuprofen","NSAID","brufen","motrin","依普芬"],"genericName":"Ibuprofen","brandNames":["Brufen","Motrin","Advil","依普芬"],"drugClass":["NSAID（非類固醇抗發炎藥）"],"highAlert":false,"indications":["關節炎","經痛","輕至中度疼痛","發燒"],"contraindications":["消化性潰瘍 / 活動性出血","嚴重腎 / 心衰竭","孕婦（尤其第三孕期）","< 6 個月嬰兒","水痘、登革熱"],"routes":["po","pr"],"doseReference":[{"population":"成人","route":"po","rangeText":"200–400 mg 每 4–6 小時，24h 總劑量 ≤ 2.4 g。","note":"僅供雙重核對；劑量以最新醫囑為準。","sourceRefIdx":0},{"population":"兒童 ≥ 6 月","route":"po","rangeText":"5–10 mg/kg/dose 每 6–8 小時，24h 總劑量 ≤ 40 mg/kg。","note":"兒科劑量請與處方對照。","sourceRefIdx":0}],"onsetPeakDuration":{"onset":"30 分鐘","peak":"1–2 小時","duration":"4–6 小時"},"adverseEffects":{"common":["腸胃不適","腹痛","頭痛"],"serious":["消化性潰瘍 / 出血","腎功能下降","血壓升高","血小板抑制"]},"monitoring":[{"parameter":"BUN / Cr","trigger":"長期使用或脫水時","actionHint":"依單位規範抽血評估腎功能。"},{"parameter":"解便顏色 / Hb","trigger":"懷疑消化道出血","actionHint":"考慮回報並依規範跟進。"}],"nursingConsiderations":["飯後服用減少胃刺激。","避免與其他 NSAIDs（含 Aspirin、Ketorolac）併用。","高血壓控制不佳、心衰竭、腎功能下降者慎用。"],"interactionsBrief":["Warfarin：增加出血風險。","ACEI / ARB：可能增加腎損傷風險。","Lithium：可能升高血中濃度。"]}'::jsonb),
('drug-bisacodyl', 'drug', 'bisacodyl', 'zh-TW', 'published', '{"id":"drug-bisacodyl","type":"drug","slug":"bisacodyl","locale":"zh-TW","title":"Bisacodyl 比沙可啶","subtitle":"刺激性瀉劑 — 樂可舒","aliases":["Bisacodyl","Dulcolax","樂可舒"],"shortSummary":"刺激大腸蠕動的瀉劑；口服腸溶錠不可咬碎或與牛奶 / 制酸劑併服。","targetUser":["nursing_student"],"clinicalSetting":["ward","opd","home","ltc"],"priority":"normal","tags":["瀉劑","基本"],"categories":["藥物/腸胃/瀉劑"],"caution":[{"level":"warning","message":"腸阻塞、急性腹症、闌尾炎禁用。長期使用可能造成電解質失衡。"}],"bodySections":[{"key":"indications","label":"適應症","layout":"bullet","collapsedByDefault":false,"displayHint":"front","content":["便秘","手術 / 大腸鏡檢查前腸道清潔"]},{"key":"nursing_focus","label":"護理重點","layout":"bullet","collapsedByDefault":false,"displayHint":"front","content":["口服腸溶錠：整粒吞服，不可咬碎，避免與牛奶 / 制酸劑同時服用（破壞腸溶外膜會造成胃刺激）。","服藥後 6–12 小時起效，建議睡前服用、晨間排便。","長期使用注意低血鉀。"]}],"quickActions":[],"references":[{"citation":"常用藥物資料庫（範例條目）","sourceType":"drug_database","sourceLang":"zh-TW"}],"review":{"version":"1.0.0","authoredBy":["seed"],"reviewedBy":[],"nextReviewDue":"2027-01-01","approvalScopes":["clinical_accuracy"]},"status":"published","createdAt":"2026-05-11T00:00:00Z","updatedAt":"2026-05-11T00:00:00Z","searchKeywords":["樂可舒","dulcolax","bisacodyl","瀉劑","便秘"],"genericName":"Bisacodyl","brandNames":["Dulcolax 樂可舒"],"drugClass":["刺激性瀉劑"],"highAlert":false,"indications":["便秘","檢查 / 手術前腸道清潔"],"contraindications":["腸阻塞","急性腹症","闌尾炎"],"routes":["po","pr"],"doseReference":[{"population":"成人","route":"po","rangeText":"5–15 mg 睡前一次。","note":"僅供雙重核對；劑量以最新醫囑為準。","sourceRefIdx":0},{"population":"成人 — 栓劑","route":"pr","rangeText":"10 mg 一顆，作用較快（15–60 分鐘）。","note":"同上。","sourceRefIdx":0}],"onsetPeakDuration":{"onset":"PO 6–12 小時；PR 15–60 分鐘"},"adverseEffects":{"common":["腹絞痛","腹瀉"],"serious":["長期使用：低血鉀、電解質失衡"]},"monitoring":[{"parameter":"排便情況 / 腹脹","trigger":"使用期間","actionHint":"紀錄頻次與性狀，異常與護理人員回報。"}],"nursingConsiderations":["不可與牛奶、制酸劑、PPI 同時服用。","睡前服，預期 6–12 小時後排便。","長期使用建議與團隊評估更替為滲透性瀉劑。"]}'::jsonb),
('drug-docusate', 'drug', 'docusate-sodium', 'zh-TW', 'published', '{"id":"drug-docusate","type":"drug","slug":"docusate-sodium","locale":"zh-TW","title":"Docusate sodium 多庫酯鈉","subtitle":"軟便劑（界面活性劑）— Colace","aliases":["Docusate","Colace","軟便寧"],"shortSummary":"降低糞便表面張力的軟便劑；適合術後 / 痔瘡病人避免用力解便，需充足水分才有效。","targetUser":["nursing_student"],"clinicalSetting":["ward","opd","home","ltc"],"priority":"normal","tags":["軟便劑","基本"],"categories":["藥物/腸胃/軟便"],"caution":[{"level":"info","message":"搭配足量水分（≥ 1500–2000 mL/day）才能發揮效果。"}],"bodySections":[{"key":"nursing_focus","label":"護理重點","layout":"bullet","collapsedByDefault":false,"displayHint":"front","content":["通常 1–3 天起效。","配合多喝水、多攝取纖維。","禁用於腸阻塞、急性腹症。"]}],"quickActions":[],"references":[{"citation":"常用藥物資料庫（範例條目）","sourceType":"drug_database","sourceLang":"zh-TW"}],"review":{"version":"1.0.0","authoredBy":["seed"],"reviewedBy":[],"nextReviewDue":"2027-01-01","approvalScopes":["clinical_accuracy"]},"status":"published","createdAt":"2026-05-11T00:00:00Z","updatedAt":"2026-05-11T00:00:00Z","searchKeywords":["docusate","colace","軟便","便秘"],"genericName":"Docusate sodium","brandNames":["Colace","軟便寧"],"drugClass":["軟便劑（界面活性劑）"],"highAlert":false,"indications":["預防便秘","痔瘡","術後避免用力解便"],"contraindications":["腸阻塞","急性腹症"],"routes":["po"],"doseReference":[{"population":"成人","route":"po","rangeText":"100 mg 每日 2–3 次。","note":"僅供雙重核對；劑量以最新醫囑為準。","sourceRefIdx":0}],"adverseEffects":{"common":["噁心","腹絞痛"],"serious":[]},"monitoring":[{"parameter":"排便情況","trigger":"使用期間","actionHint":"紀錄頻次與性狀。"}],"nursingConsiderations":["充足飲水是有效的關鍵。","不可與礦物油同時服用（可能促進吸收造成肝損傷）。"]}'::jsonb),
('drug-normal-saline', 'drug', 'normal-saline', 'zh-TW', 'published', '{"id":"drug-normal-saline","type":"drug","slug":"normal-saline","locale":"zh-TW","title":"0.9% Normal Saline 生理食鹽水","subtitle":"等張晶體輸液","aliases":["Normal Saline","N/S","0.9% NaCl","生理食鹽水","NS"],"shortSummary":"臨床最常用的等張晶體輸液；補充體液與電解質、藥物稀釋、輸血前後沖洗管路。","targetUser":["nursing_student"],"clinicalSetting":["ward","icu","er","or","opd","pediatric"],"priority":"high","tags":["輸液","基本"],"categories":["藥物/輸液"],"caution":[{"level":"warning","message":"心衰竭、腎衰竭、肝硬化水腫病人慎用。輸注時監測 I/O、肺音、下肢水腫。"},{"level":"critical","message":"輸血前後必須以 N/S 沖洗管路；不可用 D5W（會造成紅血球溶血）。"}],"bodySections":[{"key":"indications","label":"常見用途","layout":"bullet","collapsedByDefault":false,"displayHint":"front","content":["脫水補液","休克初期擴容","輸血前後沖管","藥物稀釋（多數 IV 藥物）","IV 管路維持通暢"]}],"quickActions":[],"references":[{"citation":"一般護理基礎教科書（範例條目）","sourceType":"textbook","sourceLang":"zh-TW"}],"review":{"version":"1.0.0","authoredBy":["seed"],"reviewedBy":[],"nextReviewDue":"2027-01-01","approvalScopes":["clinical_accuracy","safety_disclaimer"]},"status":"published","createdAt":"2026-05-11T00:00:00Z","updatedAt":"2026-05-11T00:00:00Z","searchKeywords":["NS","normal saline","生理食鹽水","0.9% NaCl","saline"],"genericName":"Sodium Chloride 0.9%","brandNames":["N/S","台塑生理食鹽水"],"drugClass":["等張晶體溶液"],"highAlert":false,"indications":["脫水","擴容","輸血前後沖管","藥物稀釋"],"contraindications":["嚴重心衰竭未控制","嚴重肝硬化伴大量水腫","高鈉血症"],"routes":["iv"],"doseReference":[{"population":"維持輸液（成人）","route":"iv","rangeText":"常見 80–125 mL/hr，依個別評估與醫囑調整。","note":"僅供雙重核對；速率以最新醫囑為準。","sourceRefIdx":0}],"adverseEffects":{"common":["注射部位不適"],"serious":["過量造成肺水腫","高氯性代謝性酸中毒"]},"monitoring":[{"parameter":"I/O、肺音、下肢水腫","trigger":"每班 / 依規範","actionHint":"異常與護理人員 / 醫師回報。"}],"nursingConsiderations":["輸血前後務必沖管以 N/S。","老年、心腎不全者注意輸液負荷。","高鉀血症時不可用含鉀液（如 Ringer''s）取代。"]}'::jsonb),
('drug-povidone-iodine', 'drug', 'povidone-iodine', 'zh-TW', 'published', '{"id":"drug-povidone-iodine","type":"drug","slug":"povidone-iodine","locale":"zh-TW","title":"Povidone-Iodine 優碘","subtitle":"外用消毒劑 — 必妥碘","aliases":["Betadine","必妥碘","優碘","PVP-I"],"shortSummary":"廣效殺菌外用消毒劑；新生兒、孕婦、甲狀腺疾病、碘過敏慎用 / 禁用。","targetUser":["nursing_student"],"clinicalSetting":["ward","or","er","opd","home"],"priority":"normal","tags":["消毒","外用","基本"],"categories":["藥物/外用"],"caution":[{"level":"warning","message":"對碘或海鮮過敏者禁用。新生兒、孕婦、甲狀腺疾病患者大面積長期使用可能造成甲狀腺功能異常。"}],"bodySections":[{"key":"usage","label":"使用方式","layout":"bullet","collapsedByDefault":false,"displayHint":"front","content":["以無菌棉枝由內往外環形消毒。","待自然乾燥（30 秒～2 分鐘）才有殺菌效果。","深部傷口避免直接使用（可能延遲癒合）。","使用後依醫囑可能需以 N/S 沖洗殘留。"]}],"quickActions":[],"references":[{"citation":"一般護理基礎教科書（範例條目）","sourceType":"textbook","sourceLang":"zh-TW"}],"review":{"version":"1.0.0","authoredBy":["seed"],"reviewedBy":[],"nextReviewDue":"2027-01-01","approvalScopes":["clinical_accuracy"]},"status":"published","createdAt":"2026-05-11T00:00:00Z","updatedAt":"2026-05-11T00:00:00Z","searchKeywords":["優碘","betadine","povidone","消毒","必妥碘"],"genericName":"Povidone-Iodine 10%","brandNames":["Betadine 必妥碘"],"drugClass":["外用消毒劑"],"highAlert":false,"indications":["傷口消毒","術前皮膚消毒","注射部位消毒"],"contraindications":["對碘 / 海鮮過敏","新生兒大面積使用","甲狀腺機能亢進"],"routes":["topical"],"doseReference":[{"population":"外用","route":"topical","rangeText":"依消毒部位適量塗抹，由內往外環形操作，待自然乾燥。","note":"依各院傷口照護 SOP。","sourceRefIdx":0}],"adverseEffects":{"common":["皮膚刺激","色素沉著"],"serious":["過敏反應","大面積長期使用造成甲狀腺功能異常"]},"monitoring":[{"parameter":"使用部位皮膚反應","trigger":"每次更換敷料","actionHint":"出現紅、癢、起疹須回報。"}],"nursingConsiderations":["使用前確認病人沒有碘 / 海鮮過敏史。","深部傷口、新生兒慎用。","與酒精相比殺菌譜更廣但對組織刺激較大。"]}'::jsonb),
('drug-heparin-lock', 'drug', 'heparin-lock-flush', 'zh-TW', 'published', '{"id":"drug-heparin-lock","type":"drug","slug":"heparin-lock-flush","locale":"zh-TW","title":"Heparin 肝素（沖管用）","subtitle":"⚠️ 高警訊藥品 — 沖管濃度與治療濃度差異極大","aliases":["Heparin","肝素","Heparin Lock","Heparin Flush"],"shortSummary":"中央靜脈導管維持通暢的低劑量肝素；濃度核對是最大安全焦點，治療用濃度錯打會大出血。","targetUser":["nursing_student"],"clinicalSetting":["ward","icu","er"],"priority":"critical","tags":["抗凝","high-alert","基本"],"categories":["藥物/抗凝"],"caution":[{"level":"critical","message":"⚠️ 高警訊藥品。沖管用 Heparin（U/mL）與治療用（U/kg/hr）濃度差異極大，必須三讀六對。"},{"level":"warning","message":"活動性出血、血小板 < 50,000、近期手術病人禁用。"}],"redFlags":[{"trigger":"同一抽屜混放沖管用與治療用 Heparin","actionHint":"停止取藥，與護理人員確認分區存放並依單位規範核對。"},{"trigger":"不明原因出血、瘀斑、血尿、血便","actionHint":"考慮回報並依單位規範跟進。"}],"bodySections":[{"key":"nursing_focus","label":"護理重點","layout":"bullet","collapsedByDefault":false,"displayHint":"front","content":["沖管前先 aspirate 確認回血，再以 N/S 5 mL 沖管，最後以 Heparin lock 3–5 mL 封管。","抗凝指標監測：aPTT（治療用），沖管用不需常規監測。","HIT（Heparin-induced thrombocytopenia）警訊：用藥後 5–10 天血小板顯著下降。"]}],"quickActions":[],"references":[{"citation":"院內中央靜脈導管照護 SOP（範例條目）","sourceType":"institutional_sop","sourceLang":"zh-TW"}],"review":{"version":"1.0.0","authoredBy":["seed"],"reviewedBy":[],"nextReviewDue":"2026-12-01","approvalScopes":["clinical_accuracy","safety_disclaimer"]},"status":"published","createdAt":"2026-05-11T00:00:00Z","updatedAt":"2026-05-11T00:00:00Z","searchKeywords":["heparin","肝素","CVP","port","沖管"],"genericName":"Heparin Sodium","brandNames":["Heparin Lock Flush"],"drugClass":["抗凝血劑（低劑量沖管用）"],"highAlert":true,"lasaWarnings":["Heparin（治療用）— 濃度差異極大"],"indications":["CVP / Port-A 等中央靜脈導管維持通暢"],"contraindications":["活動性出血","血小板 < 50,000","近期顱內 / 眼科 / 脊椎手術","HIT 病史"],"routes":["iv"],"doseReference":[{"population":"CVC 沖管","route":"iv","rangeText":"10–100 U/mL，每次沖洗 3–5 mL（依各院規範）。","note":"⚠️ 請確認瓶身濃度；治療用 Heparin 濃度差異極大。","sourceRefIdx":0}],"adverseEffects":{"common":["注射部位瘀青"],"serious":["出血","HIT（heparin-induced thrombocytopenia）","過敏"]},"monitoring":[{"parameter":"血小板（治療劑量）","trigger":"用藥後 5–10 天注意 HIT","actionHint":"異常與團隊回報，依規範跟進。"}],"nursingConsiderations":["⚠️ 沖管濃度與治療濃度不要放在同一抽屜，依單位規範分區存放。","解毒劑為 Protamine sulfate。","雙人核對高警訊藥品。"]}'::jsonb),
('drug-amlodipine', 'drug', 'amlodipine', 'zh-TW', 'published', '{"id":"drug-amlodipine","type":"drug","slug":"amlodipine","locale":"zh-TW","title":"Amlodipine 脈優","subtitle":"CCB — 降壓 / 心絞痛","aliases":["Amlodipine","Norvasc","脈優"],"shortSummary":"長效鈣離子通道阻斷劑；下肢水腫為最具特徵性副作用；避免葡萄柚汁。","targetUser":["nursing_student"],"clinicalSetting":["ward","opd","er"],"ageScope":["adult","elderly"],"priority":"high","tags":["CCB","cardiovascular","降壓"],"categories":["藥物/心血管/降壓"],"caution":[{"level":"warning","message":"SBP < 90 或 HR < 60 時暫停並通報。姿勢性低血壓提醒病人緩慢起身。"}],"bodySections":[{"key":"nursing_focus","label":"護理觀察重點","layout":"bullet","collapsedByDefault":false,"displayHint":"front","content":["給藥前測 BP / HR。","觀察下肢水腫、頭痛、臉潮紅、心悸、牙齦增生。","衛教避免葡萄柚汁（抑制 CYP3A4 使血中濃度升高）。"]}],"quickActions":[],"references":[{"citation":"常用藥物資料庫（範例條目）","sourceType":"drug_database","sourceLang":"zh-TW"}],"review":{"version":"1.0.0","authoredBy":["seed"],"reviewedBy":[],"nextReviewDue":"2027-01-01","approvalScopes":["clinical_accuracy"]},"status":"published","createdAt":"2026-05-11T00:00:00Z","updatedAt":"2026-05-11T00:00:00Z","searchKeywords":["脈優","amlodipine","norvasc","CCB","降壓"],"genericName":"Amlodipine","brandNames":["Norvasc 脈優"],"drugClass":["CCB（二氫吡啶類鈣離子通道阻斷劑）"],"highAlert":false,"indications":["高血壓","慢性穩定型心絞痛"],"contraindications":["對成分過敏","嚴重低血壓","心因性休克"],"routes":["po"],"doseReference":[{"population":"成人","route":"po","rangeText":"5–10 mg 每日 1 次。","note":"僅供雙重核對；劑量以最新醫囑為準。","sourceRefIdx":0}],"onsetPeakDuration":{"onset":"6–12 小時","peak":"6–9 小時","duration":"24 小時"},"adverseEffects":{"common":["下肢水腫","頭痛","臉潮紅","心悸","牙齦增生"],"serious":["嚴重低血壓","反射性心搏過速"]},"monitoring":[{"parameter":"BP / HR","trigger":"每班 / 給藥前","actionHint":"SBP < 90 或 HR < 60 暫停並回報。"},{"parameter":"下肢水腫","trigger":"每班","actionHint":"記錄並回報變化。"}],"nursingConsiderations":["避免葡萄柚汁。","提醒姿勢性低血壓，起身放慢。","長期穩定服用，不可自行停藥。"],"interactionsBrief":["Simvastatin：併用增加肌肉相關副作用風險。","CYP3A4 抑制劑：升高血中濃度。"]}'::jsonb),
('drug-furosemide', 'drug', 'furosemide', 'zh-TW', 'published', '{"id":"drug-furosemide","type":"drug","slug":"furosemide","locale":"zh-TW","title":"Furosemide 來適泄","subtitle":"⚠️ 高警訊 — 環利尿劑","aliases":["Furosemide","Lasix","腎益康","來適泄","furosemide","lasix"],"shortSummary":"迴路型利尿劑；高警訊藥品；低血鉀為重點，快速 IV push 有耳毒性風險。","targetUser":["nursing_student"],"clinicalSetting":["ward","icu","er","opd"],"priority":"high","tags":["利尿劑","high-alert","cardiovascular"],"categories":["藥物/心血管/利尿劑"],"caution":[{"level":"critical","message":"本卡為學習與雙重核對用；劑量、頻次以最新醫囑為準。"},{"level":"warning","scope":"renal","message":"腎功能不全者作用差異大，與團隊確認個別劑量。"},{"level":"warning","message":"IV push 速度 ≤ 20 mg/min，避免耳毒性。"}],"redFlags":[{"trigger":"SBP < 90 mmHg 或近期姿勢性低血壓","actionHint":"考慮暫停下一劑並通知團隊，依規範跟進。"},{"trigger":"K+ < 3.0 mmol/L 或肌肉無力 / 心律不整","actionHint":"考慮暫停給藥並回報。"}],"bodySections":[{"key":"indications","label":"常見適應症","layout":"bullet","collapsedByDefault":false,"displayHint":"front","content":["心衰竭引起之水腫","肝硬化、腎病症候群相關水腫","高血壓（合併治療）","急性肺水腫"]},{"key":"nursing_focus","label":"護理觀察重點","layout":"bullet","collapsedByDefault":false,"displayHint":"front","content":["監測 BP、HR、姿勢性血壓變化。","紀錄 I/O、體重，注意脫水徵象。","監測 K+、Na+、Mg2+、Cr / BUN。","長期使用注意聽力、痛風發作。","衛教多攝取含鉀食物（香蕉、橘子、深綠蔬菜）。","早上給藥避免夜尿。"]}],"quickActions":[{"type":"open_calculator","label":"劑量計算機"}],"references":[{"citation":"常用藥物資料庫（範例條目）","sourceType":"drug_database","sourceLang":"zh-TW"}],"review":{"version":"1.0.0","authoredBy":["seed"],"reviewedBy":[],"nextReviewDue":"2026-12-01","approvalScopes":["clinical_accuracy","safety_disclaimer"]},"status":"published","createdAt":"2026-05-11T00:00:00Z","updatedAt":"2026-05-11T00:00:00Z","searchKeywords":["lasix","furosemide","利尿劑","腎益康","來適泄"],"genericName":"Furosemide","brandNames":["Lasix","腎益康","來適泄"],"drugClass":["Loop diuretic 環利尿劑"],"highAlert":true,"lasaWarnings":["Torsemide","Fluoxetine"],"indications":["水腫","高血壓","心衰竭","急性肺水腫"],"contraindications":["無尿症","對 sulfonamide 嚴重過敏","嚴重電解質不平衡"],"routes":["po","iv","im"],"doseReference":[{"population":"成人 — 水腫","route":"po","rangeText":"20–80 mg 每日 1 次起始，依反應調整。","note":"僅供雙重核對；劑量以最新醫囑為準。","sourceRefIdx":0},{"population":"成人 — 急性肺水腫","route":"iv","rangeText":"20–40 mg 緩慢 IV（≤ 20 mg/min），必要時 1–2 小時後追加。","note":"同上。","sourceRefIdx":0}],"onsetPeakDuration":{"onset":"PO 30–60 分鐘；IV 5 分鐘","peak":"PO 1–2 小時；IV 30 分鐘","duration":"PO 6–8 小時；IV 2 小時"},"adverseEffects":{"common":["頻尿","低鉀血症","姿勢性低血壓","頭暈"],"serious":["嚴重電解質不平衡","耳毒性（快速 IV 推注）","急性腎損傷"]},"monitoring":[{"parameter":"血壓 / 心跳","trigger":"給藥前後及姿勢改變時","actionHint":"收縮壓顯著下降回報並考慮暫停下一劑。"},{"parameter":"K+, Na+, Cr","trigger":"長期 / 大劑量使用","actionHint":"依單位規範頻次抽血，異常依規範回報。"},{"parameter":"I/O","trigger":"住院期間每班","actionHint":"比較趨勢，脫水時與團隊討論。"}],"nursingConsiderations":["IV push 速率 ≤ 20 mg/min，避免耳毒性。","與 Digoxin 併用時注意低鉀引發毒性。","高警訊藥品 — 依規範雙人核對。"],"interactionsBrief":["Digoxin：低鉀時毒性風險升高（觀察性，不作交互作用判定）。","NSAIDs：降低利尿效果。","Aminoglycosides：合併使用增加耳毒性與腎毒性。"],"storage":"室溫保存，避光。","appearance":"口服錠劑為白色圓錠；注射劑為無色澄清溶液。"}'::jsonb),
('drug-nitroglycerin', 'drug', 'nitroglycerin', 'zh-TW', 'published', '{"id":"drug-nitroglycerin","type":"drug","slug":"nitroglycerin","locale":"zh-TW","title":"Nitroglycerin 耐絞寧","subtitle":"硝酸鹽 — 心絞痛急性發作","aliases":["Nitroglycerin","NTG","Nitrostat","耐絞寧","NTG patch"],"shortSummary":"快速擴張靜脈與冠狀動脈；舌下含片是急救常備；禁與 PDE-5 抑制劑（威而鋼）併用。","targetUser":["nursing_student"],"clinicalSetting":["ward","icu","er","opd"],"priority":"high","tags":["cardiovascular","心絞痛","急救"],"categories":["藥物/心血管/硝酸鹽"],"caution":[{"level":"critical","message":"⛔ 禁與 PDE-5 抑制劑（Sildenafil/Tadalafil）併用 — 會造成致命性低血壓。"},{"level":"warning","message":"給藥前測 BP，SBP < 90 不可給。貼片每日需有 10–12 小時無藥期避免抗藥性。"}],"redFlags":[{"trigger":"舌下含 3 顆（每 5 分鐘 1 顆）後胸痛仍未緩解","actionHint":"依單位規範立即通報並啟動 ACS 流程。"}],"bodySections":[{"key":"usage","label":"舌下含片使用要點","layout":"bullet","collapsedByDefault":false,"displayHint":"front","content":["坐姿含於舌下，勿吞嚥。","胸痛時 1 顆，5 分鐘無效再給，最多 3 顆仍未緩解須立即就醫。","原瓶避光保存，開封後 6 個月失效。"]}],"quickActions":[],"references":[{"citation":"常用藥物資料庫（範例條目）","sourceType":"drug_database","sourceLang":"zh-TW"}],"review":{"version":"1.0.0","authoredBy":["seed"],"reviewedBy":[],"nextReviewDue":"2026-12-01","approvalScopes":["clinical_accuracy","safety_disclaimer"]},"status":"published","createdAt":"2026-05-11T00:00:00Z","updatedAt":"2026-05-11T00:00:00Z","searchKeywords":["NTG","nitroglycerin","耐絞寧","心絞痛","nitrostat"],"genericName":"Nitroglycerin","brandNames":["Nitrostat 耐絞寧","NitroBID","NTG patch"],"drugClass":["硝酸鹽類血管擴張劑"],"highAlert":false,"indications":["心絞痛急性發作","急性心肌梗塞","高血壓急症","心衰竭"],"contraindications":["併用 PDE-5 抑制劑","嚴重低血壓 / 心因性休克","右心室梗塞"],"routes":["sl","iv","topical"],"doseReference":[{"population":"舌下含片","route":"sl","rangeText":"0.3–0.6 mg，胸痛時 1 顆，5 分鐘無效再給，最多 3 顆。","note":"僅供雙重核對；劑量以最新醫囑為準。","sourceRefIdx":0},{"population":"貼片","route":"topical","rangeText":"每日 1 片，每天需有 10–12 小時無藥期避免抗藥性。","note":"同上。","sourceRefIdx":0}],"onsetPeakDuration":{"onset":"SL 1–3 分鐘","duration":"SL 30 分鐘"},"adverseEffects":{"common":["頭痛（最常見）","臉潮紅","姿勢性低血壓","反射性心搏過速"],"serious":["嚴重低血壓","昏厥"]},"monitoring":[{"parameter":"BP","trigger":"給藥前後","actionHint":"SBP < 90 不可再給；顯著下降回報。"},{"parameter":"胸痛評估","trigger":"每次給藥前後","actionHint":"紀錄性質、強度、持續時間。"}],"nursingConsiderations":["舌下含服勿吞嚥。","貼片每天需間隔無藥期。","原瓶避光保存。"],"interactionsBrief":["PDE-5 抑制劑（Viagra 等）：致命性低血壓，絕對禁忌。"]}'::jsonb),
('drug-insulin', 'drug', 'insulin', 'zh-TW', 'published', '{"id":"drug-insulin","type":"drug","slug":"insulin","locale":"zh-TW","title":"Insulin 胰島素","subtitle":"⚠️ 高警訊 — 種類劑型多，混用錯誤風險高","aliases":["Insulin","RI","NPH","Lantus","Glargine","Aspart","NovoRapid","Humulin","胰島素"],"shortSummary":"糖尿病主力藥物；種類眾多（速效、短效、中效、長效）；最嚴重副作用為低血糖。","targetUser":["nursing_student"],"clinicalSetting":["ward","icu","er","opd"],"priority":"critical","tags":["high-alert","endocrine","diabetes"],"categories":["藥物/內分泌/糖尿病"],"caution":[{"level":"critical","message":"⚠️ 高警訊藥品 — 不同種類胰島素絕對不可混用錯誤。SC 雙人核對為原則。"},{"level":"warning","message":"Glargine（Lantus）不可與其他胰島素混合，也不可 IV。"}],"redFlags":[{"trigger":"低血糖症狀：冒冷汗、心悸、發抖、意識改變","actionHint":"立即測血糖，依單位低血糖規範處理（15g 糖、再測、回報）。"},{"trigger":"胰島素瓶身或筆型外觀與處方不符","actionHint":"停止給藥並向護理人員回報。"}],"bodySections":[{"key":"types","label":"常見胰島素分類（起效時間參考）","layout":"kv_table","collapsedByDefault":false,"displayHint":"front","content":[{"key":"速效 Aspart / Lispro","value":"5–15 分鐘 / 餐前 5–15 分打"},{"key":"短效 Regular (RI)","value":"30 分鐘 / 餐前 30 分打"},{"key":"中效 NPH","value":"2–4 小時 / 高峰約 6–10 小時"},{"key":"長效 Glargine / Detemir","value":"無明顯高峰，作用約 24 小時"}]},{"key":"nursing_focus","label":"護理觀察重點","layout":"bullet","collapsedByDefault":false,"displayHint":"front","content":["SC 注射部位輪替：腹部（吸收最快）→ 上臂 → 大腿 → 臀部。","監測血糖（餐前、餐後 2 小時、睡前、夜間）。","未開封冷藏保存；開封後室溫可放 28 天。","低血糖處理：清醒給 15g 糖（葡萄糖片、果汁），15 分鐘後重測。"]}],"quickActions":[],"references":[{"citation":"院內胰島素 SOP（範例條目）","sourceType":"institutional_sop","sourceLang":"zh-TW"}],"review":{"version":"1.0.0","authoredBy":["seed"],"reviewedBy":[],"nextReviewDue":"2026-12-01","approvalScopes":["clinical_accuracy","safety_disclaimer"]},"status":"published","createdAt":"2026-05-11T00:00:00Z","updatedAt":"2026-05-11T00:00:00Z","searchKeywords":["insulin","胰島素","lantus","novorapid","humulin","NPH","RI"],"genericName":"Insulin (Regular / NPH / Glargine / Aspart 等)","brandNames":["Humulin R/N","Lantus","Novorapid","Levemir"],"drugClass":["胰島素製劑"],"highAlert":true,"lasaWarnings":["U-100 vs U-500 濃度差異","不同廠牌胰島素筆外觀相似"],"indications":["第一型糖尿病","第二型糖尿病","DKA / HHS","住院期間血糖控制"],"contraindications":["低血糖發作中"],"routes":["sc","iv"],"doseReference":[{"population":"一般 SC 給藥","route":"sc","rangeText":"依血糖與滑動式醫囑（sliding scale）調整。","note":"請對照當班最新醫囑與血糖值；雙人核對為原則。","sourceRefIdx":0},{"population":"DKA 急性期 IV drip","route":"iv","rangeText":"0.1 U/kg/hr 起始，依血糖與血氣調整。","note":"同上。","sourceRefIdx":0}],"adverseEffects":{"common":["低血糖","注射部位脂肪萎縮 / 增生","體重增加"],"serious":["嚴重低血糖（意識變化、抽搐）","過敏"]},"monitoring":[{"parameter":"血糖","trigger":"依醫囑（常見餐前、HS、夜間）","actionHint":"異常依單位規範處置與回報。"},{"parameter":"K+","trigger":"DKA 治療期間","actionHint":"胰島素會將 K+ 推入細胞，注意低鉀。"}],"nursingConsiderations":["⚠️ 雙人核對：藥名、種類、濃度、劑量、病人。","Glargine 不可與其他胰島素混合，也不可 IV。","混合 NPH + RI 時：先抽 RI 再抽 NPH（避免污染長效瓶）。","注射部位輪替避免脂肪變化。"],"storage":"未開封冷藏 2–8°C；開封後室溫可 28 天，避免極端溫度。"}'::jsonb),
('drug-warfarin', 'drug', 'warfarin', 'zh-TW', 'published', '{"id":"drug-warfarin","type":"drug","slug":"warfarin","locale":"zh-TW","title":"Warfarin 可邁丁","subtitle":"⚠️ 高警訊 — 口服抗凝血劑","aliases":["Warfarin","Coumadin","可邁丁"],"shortSummary":"長期抗凝預防中風 / DVT / PE；以 INR 監測；飲食恆定、避免合併出血風險物。","targetUser":["nursing_student"],"clinicalSetting":["ward","opd","home"],"priority":"critical","tags":["high-alert","抗凝","cardiovascular"],"categories":["藥物/抗凝"],"caution":[{"level":"critical","message":"⚠️ 高警訊藥品；劑量、INR 目標與飲食教育是關鍵。"},{"level":"warning","scope":"pregnancy","message":"孕婦禁用（致畸胎，黑框警告）。"}],"redFlags":[{"trigger":"不明出血：牙齦出血、血尿、解黑便、瘀斑","actionHint":"考慮回報並抽 INR / PT，依規範跟進。"},{"trigger":"INR 顯著超出治療範圍","actionHint":"依單位 Warfarin 過量規範處理。"}],"bodySections":[{"key":"nursing_focus","label":"護理觀察與衛教重點","layout":"bullet","collapsedByDefault":false,"displayHint":"front","content":["監測 INR（治療目標 2–3，人工瓣膜 2.5–3.5）。","飲食恆定：深綠色蔬菜（菠菜、花椰菜、納豆）含 Vit K — 不是禁吃，是「不要忽多忽少」。","避免：阿斯匹靈、銀杏、人蔘、聖約翰草等增加出血風險。","觀察牙齦出血、血尿、瘀青、黑便。","解毒劑：Vitamin K；嚴重出血給 FFP 或 PCC。"]}],"quickActions":[],"references":[{"citation":"常用藥物資料庫（範例條目）","sourceType":"drug_database","sourceLang":"zh-TW"}],"review":{"version":"1.0.0","authoredBy":["seed"],"reviewedBy":[],"nextReviewDue":"2026-12-01","approvalScopes":["clinical_accuracy","safety_disclaimer"]},"status":"published","createdAt":"2026-05-11T00:00:00Z","updatedAt":"2026-05-11T00:00:00Z","searchKeywords":["warfarin","可邁丁","coumadin","INR","抗凝"],"genericName":"Warfarin","brandNames":["Coumadin 可邁丁"],"drugClass":["口服抗凝血劑（Vit K 拮抗劑）"],"highAlert":true,"indications":["心房顫動預防中風","DVT / PE","人工心臟瓣膜"],"contraindications":["活動性出血","嚴重肝病","懷孕","近期顱內 / 眼科手術"],"routes":["po"],"doseReference":[{"population":"成人","route":"po","rangeText":"2–10 mg 每日 1 次，依 INR 調整。","note":"僅供雙重核對；劑量以最新醫囑與 INR 為準。","sourceRefIdx":0}],"adverseEffects":{"common":["輕微出血、瘀斑"],"serious":["大出血","顱內出血","皮膚壞死（罕見）"]},"monitoring":[{"parameter":"INR","trigger":"初始與劑量調整每 2–3 天，穩定後 4–6 週","actionHint":"依規範回報異常。"},{"parameter":"出血徵象","trigger":"每日評估","actionHint":"異常立即回報。"}],"nursingConsiderations":["飲食衛教是治療成敗關鍵。","同時用藥變動（含中藥、保健食品）都可能影響 INR，需主動告知醫師。","懷孕禁用。"],"interactionsBrief":["抗生素（如 Bactrim）：升高 INR。","NSAIDs：增加出血。","銀杏、人蔘、聖約翰草：影響 INR。"]}'::jsonb),
('drug-omeprazole', 'drug', 'omeprazole', 'zh-TW', 'published', '{"id":"drug-omeprazole","type":"drug","slug":"omeprazole","locale":"zh-TW","title":"Omeprazole 樂酸克","subtitle":"PPI — 抑制胃酸","aliases":["Omeprazole","Losec","樂酸克","Nexium","Esomeprazole","Pantoprazole"],"shortSummary":"質子幫浦抑制劑；強效抑制胃酸；長期使用注意低血鎂、骨質疏鬆、感染風險。","targetUser":["nursing_student"],"clinicalSetting":["ward","icu","opd"],"priority":"normal","tags":["PPI","消化","GERD"],"categories":["藥物/腸胃/PPI"],"caution":[{"level":"info","message":"長期使用：低血鎂、骨質疏鬆、Vit B12 缺乏、C. difficile 與肺炎風險上升。"}],"bodySections":[{"key":"nursing_focus","label":"護理重點","layout":"bullet","collapsedByDefault":false,"displayHint":"front","content":["空腹（飯前 30–60 分鐘）服用效果最佳。","膠囊整粒吞服不可磨碎（腸溶設計）。","不可自行長期服用，需定期評估必要性。"]}],"quickActions":[],"references":[{"citation":"常用藥物資料庫（範例條目）","sourceType":"drug_database","sourceLang":"zh-TW"}],"review":{"version":"1.0.0","authoredBy":["seed"],"reviewedBy":[],"nextReviewDue":"2027-01-01","approvalScopes":["clinical_accuracy"]},"status":"published","createdAt":"2026-05-11T00:00:00Z","updatedAt":"2026-05-11T00:00:00Z","searchKeywords":["omeprazole","樂酸克","PPI","nexium","耐適恩"],"genericName":"Omeprazole","brandNames":["Losec 樂酸克","Nexium 耐適恩"],"drugClass":["PPI 質子幫浦抑制劑"],"highAlert":false,"indications":["消化性潰瘍","GERD","Zollinger-Ellison","預防壓力性潰瘍（ICU）","配合抗生素治療 H. pylori"],"contraindications":["對成分過敏"],"routes":["po","iv"],"doseReference":[{"population":"成人","route":"po","rangeText":"20–40 mg 每日 1 次，飯前 30–60 分鐘。","note":"僅供雙重核對；劑量以最新醫囑為準。","sourceRefIdx":0},{"population":"成人","route":"iv","rangeText":"40 mg 每日 1 次。","note":"同上。","sourceRefIdx":0}],"adverseEffects":{"common":["頭痛","腹瀉","噁心"],"serious":["低血鎂","骨質疏鬆性骨折","C. difficile 結腸炎"]},"monitoring":[{"parameter":"Mg2+","trigger":"長期使用","actionHint":"依規範頻次抽血。"}],"nursingConsiderations":["空腹服用。","膠囊整粒吞服。","長期評估必要性與風險。"]}'::jsonb),
('drug-atorvastatin', 'drug', 'atorvastatin', 'zh-TW', 'published', '{"id":"drug-atorvastatin","type":"drug","slug":"atorvastatin","locale":"zh-TW","title":"Atorvastatin 立普妥","subtitle":"Statin — 降血脂","aliases":["Atorvastatin","Lipitor","立普妥","Rosuvastatin","Crestor"],"shortSummary":"抑制肝臟膽固醇合成；最嚴重副作用為橫紋肌溶解症與肝毒性；睡前服用、避免葡萄柚汁。","targetUser":["nursing_student"],"clinicalSetting":["ward","opd","community"],"priority":"normal","tags":["Statin","cardiovascular","降血脂"],"categories":["藥物/心血管/降血脂"],"caution":[{"level":"warning","message":"出現不明原因肌肉痠痛、無力、深色尿須立即通報並驗 CK（疑似橫紋肌溶解症）。"},{"level":"warning","scope":"hepatic","message":"活動性肝病、孕婦 / 哺乳婦女禁用。"}],"redFlags":[{"trigger":"肌肉痠痛 + 深色尿 + 無力","actionHint":"考慮停藥並回報，依規範驗 CK 與 LFT。"}],"bodySections":[{"key":"nursing_focus","label":"護理重點","layout":"bullet","collapsedByDefault":false,"displayHint":"front","content":["睡前服用（夜間膽固醇合成最旺）。","避免葡萄柚汁（升高血中濃度）。","定期監測 LFT、CK。","與 Fibrate 類併用增加橫紋肌溶解風險。"]}],"quickActions":[],"references":[{"citation":"常用藥物資料庫（範例條目）","sourceType":"drug_database","sourceLang":"zh-TW"}],"review":{"version":"1.0.0","authoredBy":["seed"],"reviewedBy":[],"nextReviewDue":"2027-01-01","approvalScopes":["clinical_accuracy"]},"status":"published","createdAt":"2026-05-11T00:00:00Z","updatedAt":"2026-05-11T00:00:00Z","searchKeywords":["atorvastatin","立普妥","lipitor","statin","降血脂"],"genericName":"Atorvastatin","brandNames":["Lipitor 立普妥"],"drugClass":["HMG-CoA reductase inhibitor (Statin)"],"highAlert":false,"indications":["高膽固醇血症","心血管疾病次級預防（CAD、Stroke）"],"contraindications":["活動性肝病","懷孕 / 哺乳"],"routes":["po"],"doseReference":[{"population":"成人","route":"po","rangeText":"10–80 mg 每晚睡前 1 次。","note":"僅供雙重核對；劑量以最新醫囑為準。","sourceRefIdx":0}],"adverseEffects":{"common":["肌肉痠痛","消化不適"],"serious":["橫紋肌溶解症","肝毒性"]},"monitoring":[{"parameter":"LFT","trigger":"起始用藥與調整劑量後","actionHint":"異常與團隊回報。"},{"parameter":"CK","trigger":"懷疑肌肉症狀","actionHint":"異常考慮停藥並回報。"}],"nursingConsiderations":["睡前服用。","避免葡萄柚汁。","禁用於懷孕。"]}'::jsonb),
('drug-morphine', 'drug', 'morphine', 'zh-TW', 'published', '{"id":"drug-morphine","type":"drug","slug":"morphine","locale":"zh-TW","title":"Morphine 嗎啡","subtitle":"⚠️ 管制藥 — 強效鴉片類止痛","aliases":["Morphine","MST","嗎啡"],"shortSummary":"中重度疼痛主力；第一級管制藥；最危險副作用為呼吸抑制，解毒劑為 Naloxone。","targetUser":["nursing_student"],"clinicalSetting":["ward","icu","er","or"],"priority":"critical","tags":["鴉片","管制藥","止痛"],"categories":["藥物/止痛/鴉片"],"caution":[{"level":"critical","message":"⚠️ 第一級管制藥。雙人核對並紀錄殘餘量；呼吸抑制風險高。"},{"level":"warning","message":"RR < 10 須通報並準備 Naloxone。"}],"redFlags":[{"trigger":"RR < 10、SpO2 顯著下降、極度嗜睡或無法叫醒","actionHint":"考慮停止下一劑、保持呼吸道、給氧並通報，依規範使用 Naloxone。"},{"trigger":"頭部外傷 / 顱內壓升高病人未經團隊評估","actionHint":"暫停並回報。"}],"bodySections":[{"key":"nursing_focus","label":"護理觀察重點","layout":"bullet","collapsedByDefault":false,"displayHint":"front","content":["給藥前評估疼痛分數、RR、BP、意識、瞳孔大小。","預防性軟便劑（鴉片類常造成便秘）。","觀察噁心嘔吐、尿滯留、瘙癢。","雙人核對 + 紀錄殘餘量（管制藥規範）。","解毒劑：Naloxone。"]}],"quickActions":[],"references":[{"citation":"院內管制藥使用 SOP（範例條目）","sourceType":"institutional_sop","sourceLang":"zh-TW"}],"review":{"version":"1.0.0","authoredBy":["seed"],"reviewedBy":[],"nextReviewDue":"2026-12-01","approvalScopes":["clinical_accuracy","safety_disclaimer"]},"status":"published","createdAt":"2026-05-11T00:00:00Z","updatedAt":"2026-05-11T00:00:00Z","searchKeywords":["morphine","嗎啡","管制","止痛"],"genericName":"Morphine Sulfate","brandNames":["MST Continus","Morphine"],"drugClass":["鴉片類強效止痛劑（μ-receptor agonist）"],"highAlert":true,"indications":["中重度急慢性疼痛","癌症疼痛","心肌梗塞疼痛","肺水腫（降低前負荷與焦慮）"],"contraindications":["呼吸抑制","麻痺性腸阻塞","頭部外傷未評估"],"routes":["iv","im","sc","po"],"doseReference":[{"population":"成人 — IV/IM/SC","route":"iv","rangeText":"2–10 mg 每 4 小時 PRN。","note":"僅供雙重核對；劑量以最新醫囑為準。","sourceRefIdx":0}],"adverseEffects":{"common":["便秘","噁心嘔吐","嗜睡","瘙癢","尿滯留"],"serious":["呼吸抑制","低血壓","依賴性"]},"monitoring":[{"parameter":"RR / SpO2 / 意識","trigger":"給藥後 30 分鐘 + 每班","actionHint":"RR < 10 或意識下降回報。"},{"parameter":"疼痛分數","trigger":"給藥前後","actionHint":"紀錄評分變化。"}],"nursingConsiderations":["雙人核對 + 紀錄殘餘量。","預防性給軟便劑。","解毒劑 Naloxone 應就近備妥。"]}'::jsonb),
('drug-fentanyl', 'drug', 'fentanyl', 'zh-TW', 'published', '{"id":"drug-fentanyl","type":"drug","slug":"fentanyl","locale":"zh-TW","title":"Fentanyl 吩坦尼","subtitle":"⚠️ 管制藥 — 強效合成鴉片（約 Morphine 100×）","aliases":["Fentanyl","Duragesic","多瑞吉","吩坦尼"],"shortSummary":"麻醉、PCA、慢性癌痛貼片常用；貼片注意熱源避免過量釋放；呼吸抑制風險比 Morphine 更高。","targetUser":["nursing_student"],"clinicalSetting":["ward","icu","er","or"],"priority":"critical","tags":["鴉片","管制藥","止痛"],"categories":["藥物/止痛/鴉片"],"caution":[{"level":"critical","message":"⚠️ 管制藥。效力約 Morphine 的 100 倍，呼吸抑制風險高。"},{"level":"warning","message":"貼片避免熱源（電熱毯、發燒、熱敷）— 會加速釋放造成過量。"}],"redFlags":[{"trigger":"貼片病人發燒或使用熱敷","actionHint":"考慮回報並監測呼吸與意識。"},{"trigger":"RR < 10 或極度嗜睡","actionHint":"依單位規範處置並準備 Naloxone。"}],"bodySections":[{"key":"patch_usage","label":"貼片使用要點","layout":"bullet","collapsedByDefault":false,"displayHint":"front","content":["貼於乾燥無毛皮膚（胸前、上臂、背）。","每 72 小時更換，部位輪替。","舊貼片撕下後對折黏住丟入感染性廢棄物（避免他人接觸殘留藥物）。","發燒時吸收率上升，需通報。"]}],"quickActions":[],"references":[{"citation":"院內管制藥使用 SOP（範例條目）","sourceType":"institutional_sop","sourceLang":"zh-TW"}],"review":{"version":"1.0.0","authoredBy":["seed"],"reviewedBy":[],"nextReviewDue":"2026-12-01","approvalScopes":["clinical_accuracy","safety_disclaimer"]},"status":"published","createdAt":"2026-05-11T00:00:00Z","updatedAt":"2026-05-11T00:00:00Z","searchKeywords":["fentanyl","吩坦尼","多瑞吉","duragesic","貼片"],"genericName":"Fentanyl","brandNames":["Duragesic 多瑞吉貼片","Fentanyl citrate"],"drugClass":["強效合成鴉片類（μ-receptor agonist）"],"highAlert":true,"indications":["手術麻醉","PCA 術後止痛","慢性癌症疼痛（貼片）"],"contraindications":["呼吸抑制","對成分過敏"],"routes":["iv","topical"],"doseReference":[{"population":"貼片","route":"topical","rangeText":"12–100 mcg/hr 每 72 小時更換一次。","note":"僅供雙重核對；劑量以最新醫囑為準。","sourceRefIdx":0}],"adverseEffects":{"common":["便秘","嗜睡","噁心"],"serious":["呼吸抑制","肌肉僵直（快速 IV 推注）"]},"monitoring":[{"parameter":"RR / SpO2 / 意識","trigger":"給藥後及每班","actionHint":"RR < 10 或意識下降回報。"}],"nursingConsiderations":["貼片避免熱源。","舊貼片正確丟棄。","解毒劑 Naloxone。"]}'::jsonb),
('drug-ketorolac', 'drug', 'ketorolac', 'zh-TW', 'published', '{"id":"drug-ketorolac","type":"drug","slug":"ketorolac","locale":"zh-TW","title":"Ketorolac 克多炎","subtitle":"強效 NSAID（IV/IM）— 術後止痛","aliases":["Ketorolac","Toradol","克多炎"],"shortSummary":"強效 NSAID 注射劑；止痛接近鴉片但無中樞抑制；最多使用 5 天避免腎毒性與胃出血。","targetUser":["nursing_student"],"clinicalSetting":["ward","er","or"],"priority":"high","tags":["NSAID","止痛","術後"],"categories":["藥物/止痛/NSAID"],"caution":[{"level":"warning","message":"使用期間監測 BUN/Cr、Hb、解便顏色；最多使用 5 天。"},{"level":"warning","message":"老人劑量減半。"}],"redFlags":[{"trigger":"解黑便、血便、Hb 顯著下降","actionHint":"考慮停藥並回報，依規範跟進。"}],"bodySections":[{"key":"nursing_focus","label":"護理重點","layout":"bullet","collapsedByDefault":false,"displayHint":"front","content":["使用 ≤ 5 天。","監測腎功能與消化道出血徵象。","避免與其他 NSAIDs 併用（含 Aspirin）。"]}],"quickActions":[],"references":[{"citation":"常用藥物資料庫（範例條目）","sourceType":"drug_database","sourceLang":"zh-TW"}],"review":{"version":"1.0.0","authoredBy":["seed"],"reviewedBy":[],"nextReviewDue":"2027-01-01","approvalScopes":["clinical_accuracy"]},"status":"published","createdAt":"2026-05-11T00:00:00Z","updatedAt":"2026-05-11T00:00:00Z","searchKeywords":["ketorolac","克多炎","toradol","NSAID","術後"],"genericName":"Ketorolac Tromethamine","brandNames":["Toradol","克多炎"],"drugClass":["NSAID（強效，可注射）"],"highAlert":false,"indications":["中重度急性疼痛","術後輔助止痛"],"contraindications":["活動性消化性潰瘍","出血傾向","嚴重腎衰竭","懷孕（第三孕期）","CABG 圍術期"],"routes":["iv","im","po"],"doseReference":[{"population":"成人","route":"iv","rangeText":"15–30 mg 每 6 小時 PRN；最多使用 5 天。","note":"僅供雙重核對；劑量以最新醫囑為準。","sourceRefIdx":0}],"adverseEffects":{"common":["消化不適","頭暈"],"serious":["消化道出血","急性腎損傷"]},"monitoring":[{"parameter":"BUN / Cr","trigger":"使用期間","actionHint":"異常回報。"},{"parameter":"Hb / 解便","trigger":"使用期間","actionHint":"懷疑出血回報。"}],"nursingConsiderations":["老人劑量減半。","使用 ≤ 5 天。","不可合併其他 NSAIDs。"]}'::jsonb),
('drug-cefazolin', 'drug', 'cefazolin', 'zh-TW', 'published', '{"id":"drug-cefazolin","type":"drug","slug":"cefazolin","locale":"zh-TW","title":"Cefazolin 先鋒黴素","subtitle":"第一代頭孢菌素 — 術前預防性抗生素","aliases":["Cefazolin","Cefamezin","Ancef","先鋒黴素"],"shortSummary":"最常用術前預防性抗生素；劃刀前 30–60 分鐘給予；注意 Penicillin 過敏交叉反應。","targetUser":["nursing_student"],"clinicalSetting":["ward","or","icu"],"priority":"high","tags":["抗生素","預防","cephalosporin"],"categories":["藥物/抗生素"],"caution":[{"level":"warning","message":"對 Penicillin 過敏者約 1–10% 交叉過敏；首次給藥需依各院規範做皮膚試驗。"}],"redFlags":[{"trigger":"蕁麻疹、喉部緊縮、喘鳴、低血壓","actionHint":"可能過敏性反應 — 停藥並依單位規範急救。"}],"bodySections":[{"key":"nursing_focus","label":"護理重點","layout":"bullet","collapsedByDefault":false,"displayHint":"front","content":["給藥前詳細詢問過敏史。","術前 30–60 分鐘給予才能達最佳血中濃度。","給藥後 30 分鐘內觀察有無過敏。"]}],"quickActions":[],"references":[{"citation":"院內手術預防性抗生素 SOP（範例條目）","sourceType":"institutional_sop","sourceLang":"zh-TW"}],"review":{"version":"1.0.0","authoredBy":["seed"],"reviewedBy":[],"nextReviewDue":"2027-01-01","approvalScopes":["clinical_accuracy"]},"status":"published","createdAt":"2026-05-11T00:00:00Z","updatedAt":"2026-05-11T00:00:00Z","searchKeywords":["cefazolin","先鋒黴素","cefamezin","抗生素","術前"],"genericName":"Cefazolin","brandNames":["Cefamezin","Ancef","先鋒黴素"],"drugClass":["第一代頭孢菌素抗生素"],"highAlert":false,"indications":["術前預防性抗生素","皮膚軟組織感染","骨關節感染"],"contraindications":["對 Cephalosporin 嚴重過敏"],"routes":["iv","im"],"doseReference":[{"population":"成人","route":"iv","rangeText":"1–2 g 每 8 小時。","note":"僅供雙重核對；劑量以最新醫囑為準。","sourceRefIdx":0}],"adverseEffects":{"common":["腹瀉","皮疹","注射部位疼痛"],"serious":["過敏性休克","偽膜性結腸炎"]},"monitoring":[{"parameter":"過敏徵象","trigger":"給藥後 30 分鐘","actionHint":"出現過敏立即停藥並處置。"}],"nursingConsiderations":["詳細詢問藥物過敏史。","術前 30–60 分鐘給藥。","腹瀉持續 / 血便 → 考慮 C. difficile。"]}'::jsonb),
('drug-enoxaparin', 'drug', 'enoxaparin', 'zh-TW', 'published', '{"id":"drug-enoxaparin","type":"drug","slug":"enoxaparin","locale":"zh-TW","title":"Enoxaparin 克立生","subtitle":"LMWH — 預防 / 治療血栓","aliases":["Enoxaparin","Clexane","克立生","LMWH"],"shortSummary":"低分子量肝素；術後 DVT 預防；腹部 SC 注射，注射後不揉、不排氣泡。","targetUser":["nursing_student"],"clinicalSetting":["ward","or","icu"],"priority":"high","tags":["抗凝","LMWH"],"categories":["藥物/抗凝"],"caution":[{"level":"warning","message":"活動性出血、嚴重腎功能不全、近期顱內手術禁用。"}],"redFlags":[{"trigger":"不明出血或血小板顯著下降","actionHint":"考慮回報，懷疑 HIT 需依規範跟進。"}],"bodySections":[{"key":"injection_technique","label":"注射技巧","layout":"bullet","collapsedByDefault":false,"displayHint":"front","content":["注射於腹部肚臍周圍 5 cm 外的脂肪層。","捏起腹部脂肪、90 度進針。","預充式注射器不可排氣泡（氣泡用來封住針孔減少漏液與瘀青）。","注射後不可揉。"]}],"quickActions":[],"references":[{"citation":"常用藥物資料庫（範例條目）","sourceType":"drug_database","sourceLang":"zh-TW"}],"review":{"version":"1.0.0","authoredBy":["seed"],"reviewedBy":[],"nextReviewDue":"2027-01-01","approvalScopes":["clinical_accuracy","safety_disclaimer"]},"status":"published","createdAt":"2026-05-11T00:00:00Z","updatedAt":"2026-05-11T00:00:00Z","searchKeywords":["enoxaparin","克立生","clexane","LMWH","DVT"],"genericName":"Enoxaparin Sodium","brandNames":["Clexane 克立生"],"drugClass":["LMWH 低分子量肝素"],"highAlert":true,"indications":["術後 DVT/PE 預防","急性冠心症","不穩定性心絞痛"],"contraindications":["活動性出血","嚴重腎衰竭","近期顱內手術"],"routes":["sc"],"doseReference":[{"population":"預防","route":"sc","rangeText":"40 mg 每日 1 次。","note":"僅供雙重核對；劑量以最新醫囑為準。","sourceRefIdx":0},{"population":"治療","route":"sc","rangeText":"1 mg/kg 每 12 小時。","note":"同上。","sourceRefIdx":0}],"adverseEffects":{"common":["注射部位瘀青 / 血腫"],"serious":["出血","HIT","罕見過敏"]},"monitoring":[{"parameter":"血小板","trigger":"懷疑 HIT","actionHint":"異常回報。"},{"parameter":"出血徵象","trigger":"每班","actionHint":"異常回報。"}],"nursingConsiderations":["腹部注射、不揉、不排氣泡。","解毒劑：Protamine sulfate（部分有效）。"]}'::jsonb),
('drug-tranexamic-acid', 'drug', 'tranexamic-acid', 'zh-TW', 'published', '{"id":"drug-tranexamic-acid","type":"drug","slug":"tranexamic-acid","locale":"zh-TW","title":"Tranexamic Acid 傳明酸","subtitle":"止血劑（抗纖維蛋白溶解）","aliases":["Tranexamic Acid","TXA","Transamin","傳明酸"],"shortSummary":"抑制血塊分解止血；產後大出血、創傷出血（黃金 3 小時內）；禁用於活動性血栓栓塞。","targetUser":["nursing_student"],"clinicalSetting":["ward","or","er","obstetric"],"priority":"high","tags":["止血"],"categories":["藥物/止血"],"caution":[{"level":"warning","message":"禁用於活動性血栓栓塞（DVT、PE、急性 MI、Stroke）。快速 IV 推注會造成低血壓。"}],"bodySections":[{"key":"nursing_focus","label":"護理重點","layout":"bullet","collapsedByDefault":false,"displayHint":"front","content":["IV 速率 ≥ 1 mL/min 緩慢給予。","創傷出血 — 黃金 3 小時內給予效果最佳。","不可與避孕藥併用（增加血栓風險）。"]}],"quickActions":[],"references":[{"citation":"常用藥物資料庫（範例條目）","sourceType":"drug_database","sourceLang":"zh-TW"}],"review":{"version":"1.0.0","authoredBy":["seed"],"reviewedBy":[],"nextReviewDue":"2027-01-01","approvalScopes":["clinical_accuracy"]},"status":"published","createdAt":"2026-05-11T00:00:00Z","updatedAt":"2026-05-11T00:00:00Z","searchKeywords":["tranexamic","TXA","傳明酸","止血","transamin"],"genericName":"Tranexamic Acid","brandNames":["Transamin","TXA"],"drugClass":["抗纖維蛋白溶解劑（止血劑）"],"highAlert":false,"indications":["外科手術出血","產後大出血","月經過多","創傷大量出血"],"contraindications":["活動性血栓栓塞","色盲"],"routes":["po","iv"],"doseReference":[{"population":"成人","route":"po","rangeText":"1–1.5 g 每日 3 次。","note":"僅供雙重核對；劑量以最新醫囑為準。","sourceRefIdx":0},{"population":"成人","route":"iv","rangeText":"0.5–1 g 緩慢 IV（≥ 1 mL/min）。","note":"同上。","sourceRefIdx":0}],"adverseEffects":{"common":["噁心","腹瀉"],"serious":["姿勢性低血壓（快速 IV）","血栓事件"]},"monitoring":[{"parameter":"血栓徵象","trigger":"高危險族群","actionHint":"異常回報。"}],"nursingConsiderations":["IV 緩慢給予。","色盲者慎用。"]}'::jsonb),
('drug-lidocaine', 'drug', 'lidocaine', 'zh-TW', 'published', '{"id":"drug-lidocaine","type":"drug","slug":"lidocaine","locale":"zh-TW","title":"Lidocaine 利多卡因","subtitle":"局部麻醉 / 抗心律不整","aliases":["Lidocaine","Xylocaine","利度卡因","利多卡因"],"shortSummary":"最常用局部麻醉劑；含 Epinephrine 劑型禁用於肢端；注射前 aspirate 確認無回血。","targetUser":["nursing_student"],"clinicalSetting":["or","er","ward","icu"],"priority":"high","tags":["麻醉","局部"],"categories":["藥物/麻醉"],"caution":[{"level":"critical","message":"含 Epinephrine 劑型禁用於肢端（手指、腳趾、耳、陰莖）— 會造成缺血壞死。"},{"level":"warning","message":"LAST（全身性局麻毒性）：口周麻木、耳鳴、頭暈→抽搐→心律不整。"}],"redFlags":[{"trigger":"口周麻木、耳鳴、躁動、意識變化","actionHint":"可能為 LAST — 停止給藥並依規範急救。"}],"bodySections":[{"key":"nursing_focus","label":"護理重點","layout":"bullet","collapsedByDefault":false,"displayHint":"front","content":["注射前 aspirate 確認無回血，避免誤入血管。","含 Epinephrine 劑型不可用於肢端。","對 Amide 類局麻過敏者禁用。"]}],"quickActions":[],"references":[{"citation":"常用藥物資料庫（範例條目）","sourceType":"drug_database","sourceLang":"zh-TW"}],"review":{"version":"1.0.0","authoredBy":["seed"],"reviewedBy":[],"nextReviewDue":"2027-01-01","approvalScopes":["clinical_accuracy","safety_disclaimer"]},"status":"published","createdAt":"2026-05-11T00:00:00Z","updatedAt":"2026-05-11T00:00:00Z","searchKeywords":["lidocaine","利多卡因","xylocaine","局部麻醉"],"genericName":"Lidocaine","brandNames":["Xylocaine"],"drugClass":["局部麻醉劑（Amide）/ 抗心律不整（Class Ib）"],"highAlert":false,"indications":["局部浸潤麻醉","傷口縫合","胸管置入","IV 導管置入止痛","致命性室性心律不整（IV）"],"contraindications":["對 Amide 類過敏","完全性心傳導阻滯（除非有 pacemaker）"],"routes":["topical","sc","iv","im"],"doseReference":[{"population":"局部浸潤","route":"sc","rangeText":"1–2% 局部浸潤；含 Epinephrine 劑型禁用於肢端。","note":"劑量以最新醫囑為準。","sourceRefIdx":0}],"adverseEffects":{"common":["注射部位疼痛"],"serious":["LAST（全身性局麻毒性）：抽搐、心律不整、心跳停止"]},"monitoring":[{"parameter":"LAST 徵象","trigger":"給藥後","actionHint":"異常立即停藥並急救。"}],"nursingConsiderations":["注射前 aspirate。","肢端避免 Epinephrine 劑型。"]}'::jsonb),
