('drug-risperidone', 'drug', 'risperidone', 'zh-TW', 'published', '{"id":"drug-risperidone","type":"drug","slug":"risperidone","locale":"zh-TW","title":"Risperidone 理斯必妥","subtitle":"第二代抗精神病藥","aliases":["Risperidone","Risperdal","理斯必妥","Consta"],"shortSummary":"非典型抗精神病藥；EPS 少於 Haloperidol，但代謝症候群與高泌乳素血症較明顯。","targetUser":["nursing_student"],"clinicalSetting":["ward","opd","community"],"priority":"high","tags":["抗精神病","精神"],"categories":["藥物/精神/抗精神病"],"caution":[{"level":"warning","message":"代謝症候群（體重、血糖、血脂上升）需定期監測。姿勢性低血壓提醒緩慢起身。"}],"bodySections":[{"key":"nursing_focus","label":"護理重點","layout":"bullet","collapsedByDefault":false,"displayHint":"front","content":["定期監測體重、BMI、血糖、血脂。","衛教飲食控制與規律運動。","緩慢起身避免跌倒。"]}],"quickActions":[],"references":[{"citation":"常用藥物資料庫（範例條目）","sourceType":"drug_database","sourceLang":"zh-TW"}],"review":{"version":"1.0.0","authoredBy":["seed"],"reviewedBy":[],"nextReviewDue":"2027-01-01","approvalScopes":["clinical_accuracy"]},"status":"published","createdAt":"2026-05-11T00:00:00Z","updatedAt":"2026-05-11T00:00:00Z","searchKeywords":["risperidone","理斯必妥","risperdal"],"genericName":"Risperidone","brandNames":["Risperdal 理斯必妥","Consta（長效針劑）"],"drugClass":["第二代（非典型）抗精神病藥"],"highAlert":false,"indications":["思覺失調","躁鬱症","自閉症兒童躁動"],"contraindications":["對成分過敏"],"routes":["po","im"],"doseReference":[{"population":"成人","route":"po","rangeText":"1–6 mg 每日 1–2 次。","note":"僅供雙重核對；劑量以最新醫囑為準。","sourceRefIdx":0}],"adverseEffects":{"common":["嗜睡","體重增加","姿勢性低血壓","高泌乳素（月經失調、男性女乳）"],"serious":["代謝症候群","EPS（較少）","NMS"]},"monitoring":[{"parameter":"體重 / 血糖 / 血脂","trigger":"每 3–6 個月","actionHint":"異常回報。"}],"nursingConsiderations":["監測代謝指標。","緩慢起身。"]}'::jsonb),
('drug-sertraline', 'drug', 'sertraline', 'zh-TW', 'published', '{"id":"drug-sertraline","type":"drug","slug":"sertraline","locale":"zh-TW","title":"Sertraline 樂復得","subtitle":"SSRI — 抗憂鬱 / 焦慮","aliases":["Sertraline","Zoloft","樂復得","SSRI"],"shortSummary":"SSRI 類抗憂鬱藥；< 25 歲族群黑框警告（自殺意念）；藥效需 2–4 週顯著。","targetUser":["nursing_student"],"clinicalSetting":["ward","opd","community"],"priority":"high","tags":["抗憂鬱","SSRI","精神"],"categories":["藥物/精神/抗憂鬱"],"caution":[{"level":"critical","message":"⚠️ 黑框警告：< 25 歲族群可能增加自殺意念。首 1–2 個月密切觀察。"},{"level":"warning","message":"與 MAOI、Tramadol、Triptan 併用可能造成血清素症候群。"}],"redFlags":[{"trigger":"高燒 + 肌肉僵直 + 躁動 + 抽搐（血清素症候群）","actionHint":"立即停藥並依規範急救。"},{"trigger":"出現自殺意念或自殘行為","actionHint":"立即評估安全並通報團隊。"}],"bodySections":[{"key":"nursing_focus","label":"護理重點","layout":"bullet","collapsedByDefault":false,"displayHint":"front","content":["藥效需 2–4 週才顯著，衛教不可自行停藥。","逐漸減藥避免戒斷症狀。","早上服用（避免失眠）。"]}],"quickActions":[],"references":[{"citation":"常用藥物資料庫（範例條目）","sourceType":"drug_database","sourceLang":"zh-TW"}],"review":{"version":"1.0.0","authoredBy":["seed"],"reviewedBy":[],"nextReviewDue":"2027-01-01","approvalScopes":["clinical_accuracy","safety_disclaimer"]},"status":"published","createdAt":"2026-05-11T00:00:00Z","updatedAt":"2026-05-11T00:00:00Z","searchKeywords":["sertraline","樂復得","zoloft","SSRI","抗憂鬱"],"genericName":"Sertraline","brandNames":["Zoloft 樂復得"],"drugClass":["SSRI 選擇性血清素再回收抑制劑"],"highAlert":false,"indications":["憂鬱症","焦慮症","強迫症","PTSD","恐慌症"],"contraindications":["併用 MAOI 14 天內","對成分過敏"],"routes":["po"],"doseReference":[{"population":"成人","route":"po","rangeText":"25–200 mg 每日 1 次（早上）。","note":"僅供雙重核對；劑量以最新醫囑為準。","sourceRefIdx":0}],"adverseEffects":{"common":["噁心","頭痛","失眠","性功能障礙","體重變化"],"serious":["血清素症候群","自殺意念上升（< 25 歲）"]},"monitoring":[{"parameter":"情緒 / 自殺意念","trigger":"首 1–2 個月","actionHint":"異常立即回報。"}],"nursingConsiderations":["藥效需 2–4 週。","不可突然停藥。","避免與 MAOI 併用。"],"interactionsBrief":["MAOI / Tramadol / Triptan：血清素症候群風險。"]