('drug-oxytocin', 'drug', 'oxytocin', 'zh-TW', 'published', '{"id":"drug-oxytocin","type":"drug","slug":"oxytocin","locale":"zh-TW","title":"Oxytocin 催產素","subtitle":"⚠️ 高警訊 — 子宮收縮劑","aliases":["Oxytocin","Pitocin","Syntocinon","催產素"],"shortSummary":"催生、加強產程、產後止血主力；過度收縮會導致胎兒窘迫或子宮破裂，需持續 CTG 監測。","targetUser":["nursing_student"],"clinicalSetting":["obstetric","or"],"ageScope":["pregnant"],"priority":"critical","tags":["high-alert","產科","子宮收縮"],"categories":["藥物/產科/子宮收縮劑"],"caution":[{"level":"critical","message":"⚠️ 高警訊。需持續監測子宮收縮與胎心音（CTG）。"},{"level":"warning","message":"禁忌：胎位不正、頭骨盆不對稱、前置胎盤、子宮疤痕。"}],"redFlags":[{"trigger":"收縮 > 5 次/10 分鐘 或 持續 ≥ 90 秒","actionHint":"立即停藥、左側臥、給氧、IV fluid，依規範處置；必要時依醫囑給 Terbutaline 鬆弛。"},{"trigger":"胎心音減速 / 失去 variability","actionHint":"依胎兒窘迫處置規範跟進。"}],"bodySections":[{"key":"nursing_focus","label":"護理觀察重點","layout":"bullet","collapsedByDefault":false,"displayHint":"front","content":["由低劑量起調（每 20–30 分鐘評估後調整）。","持續 CTG 監測子宮收縮與胎心音。","注意水中毒徵象（抗利尿作用）。","產後 10–40 U/L IV drip 用於止血。"]}],"quickActions":[],"references":[{"citation":"台北醫學大學附設醫院衛教資料（範例條目）","sourceType":"institutional_sop","sourceLang":"zh-TW"}],"review":{"version":"1.0.0","authoredBy":["seed"],"reviewedBy":[],"nextReviewDue":"2026-12-01","approvalScopes":["clinical_accuracy","safety_disclaimer"]},"status":"published","createdAt":"2026-05-11T00:00:00Z","updatedAt":"2026-05-11T00:00:00Z","searchKeywords":["oxytocin","pitocin","催產素","syntocinon"],"genericName":"Oxytocin","brandNames":["Pitocin","Syntocinon"],"drugClass":["子宮收縮劑（內分泌荷爾蒙）"],"highAlert":true,"indications":["催生 / 引產","加強產程","預防 / 治療產後出血","刺激泌乳"],"contraindications":["胎位不正","頭骨盆不對稱","前置胎盤","子宮疤痕","胎兒窘迫"],"routes":["iv","im"],"doseReference":[{"population":"催生 / 引產 IV drip","route":"iv","rangeText":"由 1–2 mU/min 起，每 20–30 分鐘調整。","note":"僅供雙重核對；劑量以最新醫囑為準。","sourceRefIdx":0},{"population":"產後止血 IV drip","route":"iv","rangeText":"10–40 U/L 加入 IV fluid 滴注。","note":"同上。","sourceRefIdx":0}],"adverseEffects":{"common":["噁心","低血壓（快速 I