('drug-diphenhydramine', 'drug', 'diphenhydramine', 'zh-TW', 'published', '{"id":"drug-diphenhydramine","type":"drug","slug":"diphenhydramine","locale":"zh-TW","title":"Diphenhydramine 苯海拉明","subtitle":"第一代抗組織胺 — 過敏 / EPS 解救","aliases":["Diphenhydramine","Vena","Benadryl","苯海拉明"],"shortSummary":"抗組織胺；過敏反應、暈車、鎮靜、急性肌張力不全解救；< 2 歲嬰幼兒避免使用。","targetUser":["nursing_student"],"clinicalSetting":["ward","er","opd","pediatric"],"priority":"high","tags":["抗組織胺","pediatric"],"categories":["藥物/抗組織胺"],"caution":[{"level":"warning","scope":"pediatric","message":"< 2 歲嬰幼兒避免使用（FDA 警告）。兒童可能出現矛盾反應（過動、興奮）。"},{"level":"warning","scope":"geriatric","message":"老人因抗膽鹼作用易跌倒、譫妄。"}],"bodySections":[{"key":"nursing_focus","label":"護理重點","layout":"bullet","collapsedByDefault":false,"displayHint":"front","content":["衛教服藥後勿操作機械、勿與酒精併用。","老人慎用。","可用於 EPS 急性肌張力不全解救。"]}],"quickActions":[],"references":[{"citation":"常用藥物資料庫（範例條目）","sourceType":"drug_database","sourceLang":"zh-TW"}],"review":{"version":"1.0.0","authoredBy":["seed"],"reviewedBy":[],"nextReviewDue":"2027-01-01","approvalScopes":["clinical_accuracy"]},"status":"published","createdAt":"2026-05-11T00:00:00Z","updatedAt":"2026-05-11T00:00:00Z","searchKeywords":["diphenhydramine","苯海拉明","vena","benadryl","抗組織胺"],"genericName":"Diphenhydramine","brandNames":["Vena","Benadryl"],"drugClass":["第一代抗組織胺（H1 拮抗劑）"],"highAlert":false,"indications":["過敏反應","暈車止吐","輕度鎮靜","EPS 急性肌張力不全"],"contraindications":["新生兒","哺乳婦女","急性窄角型青光眼"],"routes":["po","iv","im"],"doseReference":[{"population":"兒童","route":"po","rangeText":"1–1.25 mg/kg/dose 每 6 小時。","note":"僅供雙重核對；兒科劑量請與處方對照。","sourceRefIdx":0}],"adverseEffects":{"common":["嗜睡","口乾","視力模糊"],"serious":["尿滯留","譫妄（老人）"]},"monitoring":[],"nursingConsiderations":["< 2 歲避免使用。","老人慎用。"]}'::jsonb),
('drug-ors', 'drug', 'oral-rehydration-solution', 'zh-TW', 'published', '{"id":"drug-ors","type":"drug","slug":"oral-rehydration-solution","locale":"zh-TW","title":"ORS 口服電解質補充液","subtitle":"輕度脫水首選 — 急性腸胃炎","aliases":["ORS","Oral Rehydration","電解質水","寶礦力"],"shortSummary":"葡萄糖共運送機制促進腸道吸收水分；少量多次餵食；運動飲料糖分過高不建議幼兒使用。","targetUser":["nursing_student"],"clinicalSetting":["ward","opd","pediatric","home"],"priority":"high","tags":["補液","pediatric"],"categories":["藥物/腸胃/補液"],"caution":[{"level":"info","message":"少量多次餵食（每 5–10 分鐘 5–10 mL），一次太多會誘發嘔吐。"}],"redFlags":[{"trigger":"嚴重脫水、休克、頻繁嘔吐無法口服","actionHint":"依規範改 IV 輸液。"}],"bodySections":[{"key":"dosing","label":"建議劑量（兒童）","layout":"kv_table","collapsedByDefault":false,"displayHint":"front","content":[{"key":"輕度脫水","value":"50 mL/kg 於 4 小時內"},{"key":"中度脫水","value":"100 mL/kg 於 4 小時內"},{"key":"建議節奏","value":"每 5–10 分鐘 5–10 mL，避免嘔吐"}]},{"key":"nursing_focus","label":"護理重點","layout":"bullet","collapsedByDefault":false,"displayHint":"front","content":["觀察脫水改善指標：尿量、淚液、皮膚彈性、囪門凹陷。","幼兒不建議用運動飲料（糖分過高、電解質不平衡）。"]}],"quickActions":[],"references":[{"citation":"兒科腸胃炎照護指引（範例條目）","sourceType":"guideline","sourceLang":"zh-TW"}],"review":{"version":"1.0.0","authoredBy":["seed"],"reviewedBy":[],"nextReviewDue":"2027-01-01","approvalScopes":["clinical_accuracy"]},"status":"published","createdAt":"2026-05-11T00:00:00Z","updatedAt":"2026-05-11T00:00:00Z","searchKeywords":["ORS","電解質水","脫水","腸胃炎"],"genericName":"Glucose + Electrolytes Solution","brandNames":["WHO ORS","兒童電解質水（依品牌）"],"drugClass":["口服電解質補充液"],"highAlert":false,"indications":["急性腸胃炎輕度脫水"],"contraindications":["嚴重脫水 / 休克","頻繁嘔吐無法口服","腸阻塞"],"routes":["po"],"doseReference":[{"population":"兒童 — 輕度脫水","route":"po","rangeText":"50 mL/kg 於 4 小時內。","note":"兒科劑量請與處方對照。","sourceRefIdx":0},{"population":"兒童 — 中度脫水","route":"po","rangeText":"100 mL/kg 於 4 小時內。","note":"同上。","sourceRefIdx":0}],"adverseEffects":{"common":["若一次給太多可能嘔吐"],"serious":[]},"monitoring":[{"parameter":"脫水指標 / 尿量","trigger":"