('drug-glimepiride', 'drug', 'glimepiride', 'zh-TW', 'published', '{"id":"drug-glimepiride","type":"drug","slug":"glimepiride","locale":"zh-TW","title":"Glimepiride 磺醯尿素降糖藥","subtitle":"SU — 第二型糖尿病","aliases":["Glimepiride","Glipizide","Glibenclamide","Amaryl","Glucotrol"],"shortSummary":"促胰島素分泌口服降糖藥；最重要副作用是低血糖；老人風險高。","targetUser":["nursing_student"],"clinicalSetting":["ward","opd","community"],"ageScope":["adult","elderly"],"priority":"high","tags":["SU","diabetes","community"],"categories":["藥物/內分泌/糖尿病"],"caution":[{"level":"warning","message":"低血糖風險 — 規律進食、隨身糖果。"},{"level":"warning","scope":"geriatric","message":"老人慎用，長效劑型（如 Glibenclamide）低血糖時間長。"}],"redFlags":[{"trigger":"冒冷汗、心悸、頭暈、意識改變","actionHint":"立即測血糖，依單位低血糖規範處理。"}],"bodySections":[{"key":"nursing_focus","label":"護理重點","layout":"bullet","collapsedByDefault":false,"displayHint":"front","content":["早餐前服用；不可跳餐。","隨身攜帶糖果。","磺胺類過敏者慎用。"]}],"quickActions":[],"references":[{"citation":"常用藥物資料庫（範例條目）","sourceType":"drug_database","sourceLang":"zh-TW"}],"review":{"version":"1.0.0","authoredBy":["seed"],"reviewedBy":[],"nextReviewDue":"2027-01-01","approvalScopes":["clinical_accuracy","safety_disclaimer"]},"status":"published","createdAt":"2026-05-11T00:00:00Z","updatedAt":"2026-05-11T00:00:00Z","searchKeywords":["glimepiride","amaryl","glipizide","SU","糖尿病"],"genericName":"Glimepiride","brandNames":["Amaryl","Glucotrol（Glipizide）"],"drugClass":["磺醯尿素類（SU）口服降血糖藥"],"highAlert":false,"indications":["第二型糖尿病"],"contraindications":["第一型糖尿病","DKA","嚴重肝腎功能不全","磺胺類嚴重過敏"],"routes":["po"],"doseReference":[{"population":"成人","route":"po","rangeText":"1–8 mg 每日 1 次早餐前。","note":"僅供雙重核對；劑量以最新醫囑為準。","sourceRefIdx":0}],"adverseEffects":{"common":["體重增加"],"serious":["低血糖（老人風險高）"]},"monitoring":[{"parameter":"血糖","trigger":"依醫囑","actionHint":"異常依規範處置。"}],"nursingConsiderations":["早餐前服用。","不可跳餐。"]}'::jsonb),
('drug-aspirin', 'drug', 'aspirin-low-dose', 'zh-TW', 'published', '{"id":"drug-aspirin","type":"drug","slug":"aspirin-low-dose","locale":"zh-TW","title":"Aspirin 低劑量（心血管預防）","subtitle":"抗血小板 — 心血管次級預防","aliases":["Aspirin","ASA","Bokey","阿斯匹靈"],"shortSummary":"低劑量（75–100 mg）抗血小板；手術或拔牙前 5–7 天停用；< 18 歲發燒禁用（Reye 症候群）。","targetUser":["nursing_student"],"clinicalSetting":["ward","opd","community"],"priority":"high","tags":["抗血小板","cardiovascular","community"],"categories":["藥物/心血管/抗血小板"],"caution":[{"level":"warning","scope":"pediatric","message":"< 18 歲發燒禁用（Reye 症候群風險）。"},{"level":"warning","message":"手術或拔牙前 5–7 天依醫囑停用。"}],"redFlags":[{"trigger":"黑便 / 血尿 / 大瘀斑","actionHint":"考慮回報並抽血評估，依規範跟進。"}],"bodySections":[{"key":"nursing_focus","label":"護理重點","layout":"bullet","collapsedByDefault":false,"displayHint":"front","content":["飯後服用。","觀察出血徵象。","氣喘患者可能誘發（Samter''s triad）。"]}],"quickActions":[],"references":[{"citation":"常用藥物資料庫（範例條目）","sourceType":"drug_database","sourceLang":"zh-TW"}],"review":{"version":"1.0.0","authoredBy":["seed"],"reviewedBy":[],"nextReviewDue":"2027-01-01","approvalScopes":["clinical_accuracy"]},"status":"published","createdAt":"2026-05-11T00:00:00Z","updatedAt":"2026-05-11T00:00:00Z","searchKeywords":["aspirin","ASA","阿斯匹靈","bokey"],"genericName":"Aspirin (Acetylsalicylic Acid)","brandNames":["Bokey","Aspirin 100 mg"],"drugClass":["抗血小板劑 / NSAID"],"highAlert":false,"indications":["心血管疾病次級預防（CAD、Stroke）"],"contraindications":["活動性消化性潰瘍","出血傾向","Aspirin 過敏","< 18 歲發燒"],"routes":["po"],"doseReference":[{"population":"成人 — 心血管預防","route":"po","rangeText":"81–100 mg 每日 1 次（飯後）。","note":"僅供雙重核對；劑量以最新醫囑為準。","sourceRefIdx":0}],"adverseEffects":{"common":["消化不適"],"serious":["消化道出血","過敏","Reye 症候群（兒童）"]},"monitoring":[{"parameter":"出血徵象","trigger":"每次評估","actionHint":"異常回報。"}],"nursingConsiderations":["手術 / 拔牙前停用。","飯後服用。"]}'::jsonb),
('drug-influenza-vaccine', 'drug', 'influenza-vaccine', 'zh-TW', 'published', '{"id":"drug-influenza-vaccine","type":"drug","slug":"influenza-vaccine","locale":"zh-TW","title":"Influenza Vaccine 流感疫苗","subtitle":"不活化疫苗 — 季節性接種","aliases":["Influenza Vaccine","Vaxigrip","Fluarix","流感疫苗"],"shortSummary":"6 個月以上建議接種；對蛋類嚴重過敏、過去 GBS 病史禁用；接種後留觀 15–30 分鐘。","targetUser":["nursing_student"],"clinicalSetting":["opd","community","home"],"priority":"normal","tags":["疫苗","community"],"categories":["藥物/預防/疫苗"],"caution":[{"level":"warning","message":"禁忌：對蛋類嚴重過敏、過去 GBS、急性發燒。"}],"bodySections":[{"key":"nursing_focus","label":"護理重點","layout":"bullet","collapsedByDefault":false,"displayHint":"front","content":["接種前評估過敏史與健康狀態。","接種後留觀 15–30 分鐘。","衛教效力約 6 個月，每年接種。"]}],"quickActions":[],"references":[{"citation":"疾管署流感疫苗接種指引（範例條目）","sourceType":"guideline","sourceLang":"zh-TW"}],"review":{"version":"1.0.0","authoredBy":["seed"],"reviewedBy":[],"nextReviewDue":"2027-01-01","approvalScopes":["clinical_accuracy"]},"status":"published","createdAt":"2026-05-11T00:00:00Z","updatedAt":"2026-05-11T00:00:00Z","searchKeywords":["流感疫苗","influenza vaccine","vaxigrip"],"genericName":"Inactivated Influenza Vaccine","brandNames":["Vaxigrip","Fluarix"],"drugClass":["不活化疫苗"],"highAlert":false,"indications":["6 個月以上一般人預防流感"],"contraindications":["對蛋類嚴重過敏","過去 GBS 病史","急性發燒"],"routes":["im"],"doseReference":[{"population":"一般","route":"im","rangeText":"0.5 mL 三角肌（成人）；< 1 歲嬰兒大腿外側股外側肌。","note":"依年度疫苗政策。","sourceRefIdx":0}],"adverseEffects":{"common":["注射部位紅腫","低燒","肌肉痠痛"],"serious":["過敏反應","GBS（極罕見）"]},"monitoring":[{"parameter":"過敏徵象","trigger":"接種後 15–30 分鐘","actionHint":"異常立即處置。"}],"nursingConsiderations":["評估過敏史。","接種後留觀。"]}'::jsonb),
