('drug-calcium-vit-d', 'drug', 'calcium-vitamin-d', 'zh-TW', 'published', '{"id":"drug-calcium-vit-d","type":"drug","slug":"calcium-vitamin-d","locale":"zh-TW","title":"Calcium + Vitamin D 鈣與維生素 D","subtitle":"骨質疏鬆預防與治療","aliases":["Calcium","Vitamin D","Caltrate","Citracal","鈣片"],"shortSummary":"骨質疏鬆預防；Calcium Carbonate 飯後吃、Calcium Citrate 空腹皆可；避免與鐵劑 / Levothyroxine / 四環黴素同時服用。","targetUser":["nursing_student"],"clinicalSetting":["opd","community","home"],"ageScope":["adult","elderly","pregnant"],"priority":"normal","tags":["鈣","維生素","骨質疏鬆","community"],"categories":["藥物/營養補充"],"caution":[{"level":"info","message":"過量可能高血鈣與腎結石。便秘為最常見副作用。"}],"bodySections":[{"key":"nursing_focus","label":"護理重點","layout":"bullet","collapsedByDefault":false,"displayHint":"front","content":["Calcium Carbonate 飯後服用（需胃酸）；Calcium Citrate 空腹或飯後皆可（PPI 使用者建議用此）。","單次 ≤ 500 mg 吸收較佳，分次服用。","與鐵劑、Levothyroxine、四環黴素、Bisphosphonate 間隔 2 小時。","多攝取水分與纖維預防便秘。","規律日曬促進 Vit D 自合成。"]}],"quickActions":[],"references":[{"citation":"骨質疏鬆預防指引（範例條目）","sourceType":"guideline","sourceLang":"zh-TW"}],"review":{"version":"1.0.0","authoredBy":["seed"],"reviewedBy":[],"nextReviewDue":"2027-01-01","approvalScopes":["clinical_accuracy"]},"status":"published","createdAt":"2026-05-11T00:00:00Z","updatedAt":"2026-05-11T00:00:00Z","searchKeywords":["calcium","鈣","vitamin D","caltrate","骨質疏鬆"],"genericName":"Calcium Carbonate / Citrate + Cholecalciferol (D3)","brandNames":["Caltrate","Citracal"],"drugClass":["礦物質 / 維生素補充劑"],"highAlert":false,"indications":["骨質疏鬆預防 / 治療","停經後婦女","長者","缺鈣飲食族群"],"contraindications":["高血鈣","腎結石病史"],"routes":["po"],"doseReference":[{"population":"成人","route":"po","rangeText":"Calcium 500–1200 mg/day 分次；Vit D 800–1000 IU/day。","note":"單次 ≤ 500 mg 吸收較佳。","sourceRefIdx":0}],"adverseEffects":{"common":["便秘","腹脹"],"serious":["高血鈣","腎結石"]},"monitoring":[{"parameter":"便秘 / 腹脹","trigger":"使用期間","actionHint":"依需要調整劑型或合併軟便。"}],"nursingConsiderations":["Carbonate 飯後 / Citrate 不拘。","與鐵劑、Levothyroxine 間隔 2 小時。"]}'::jsonb),
('dis-001', 'disease', 'hypertension', 'zh-TW', 'published', '{"id":"dis-001","type":"disease","slug":"hypertension","locale":"zh-TW","title":"高血壓 (Hypertension)","subtitle":"原發性 / 續發性","aliases":["HTN","high blood pressure","高血壓","hypertension"],"shortSummary":"長期收縮壓 ≥ 130 mmHg 或舒張壓 ≥ 80 mmHg（依各國指引）所形成的慢性疾病；多數無症狀。","targetUser":["nursing_student"],"clinicalSetting":["ward","opd","community","home"],"ageScope":["adult","elderly","pregnant"],"priority":"high","tags":["cardiovascular","常見疾病"],"categories":["疾病/心血管/高血壓"],"caution":[{"level":"warning","message":"本卡為學習用一般知識，不可作為個別病人之診斷或治療依據。個別治療與用藥以主治醫師判斷與最新醫囑為準。"}],"bodySections":[{"key":"risk_factors","label":"常見危險因子","layout":"bullet","collapsedByDefault":false,"displayHint":"expanded","content":["家族病史、年齡、高鈉飲食、肥胖。","吸菸、酗酒、缺乏運動、長期壓力。","慢性腎臟病、糖尿病、睡眠呼吸中止症。"]},{"key":"symptoms","label":"可能表現","layout":"bullet","collapsedByDefault":false,"displayHint":"expanded","content":["多數無明顯症狀（「沉默殺手」）。","頭痛、頭暈、後頸僵硬、視力模糊（可能伴隨血壓急升）。","出現胸痛、呼吸困難、意識變化 → 考慮高血壓危象，依規範緊急回報。"]}],"quickActions":[],"references":[{"citation":"一般護理基礎教科書（範例條目）","sourceType":"textbook","sourceLang":"zh-TW"}],"review":{"version":"1.0.0","authoredBy":["seed"],"reviewedBy":[],"nextReviewDue":"2027-01-01","approvalScopes":["clinical_accuracy","language"]},"status":"published","createdAt":"2026-01-01T00:00:00Z","updatedAt":"2026-04-01T00:00:00Z","searchKeywords":["HTN","高血壓","hypertension"],"icd10":["I10"],"oneLinerDefinition":"長期動脈血壓升高的慢性疾病，多數無症狀但長期累積心血管事件風險。","pathophysiologyBrief":"心輸出量與週邊血管阻力上升導致動脈壓持續升高；可分為原發性（無單一病因）與續發性（特定病因如腎血管、內分泌）。","typicalPresentation":["多數無症狀","偶有頭痛、頭暈、視力模糊","高血壓危象時出現胸痛、呼吸困難、意識變化"],"keyInvestigations":["多次門診血壓量測（不同時段）","居家血壓監測 (HBPM)","基本血液生化（電解質、Cr、血糖、血脂）","尿液檢查（蛋白尿）、心電圖、必要時超音波"],"treatmentOverview":"治療概念包括生活型態介入（低鈉飲食、規律運動、體重控制、戒菸限酒）與藥物治療（依個別狀況考慮 ACEi、ARB、CCB、Diuretics、β-blockers 等類別）。本段為學習概念，個別處方以主治醫師判斷為準。","nursingPriorities":[{"priority":"critical","point":"監測血壓趨勢與用藥反應","rationale":"單一測值不足以下結論；以多次趨勢與用藥前後比較更具臨床意義。"},{"priority":"high","point":"評估姿勢性低血壓與跌倒風險","rationale":"尤其老年與起始 / 加量降壓藥階段。"},{"priority":"high","point":"生活型態衛教（飲食、運動、睡眠、戒菸）"},{"priority":"normal","point":"用藥順從性追蹤與副作用觀察"}],"complications":["冠心症","心衰竭","腦血管事件","慢性腎臟病","視網膜病變"],"patientEducationIds":["edu-001"],"relatedDrugIds":["drug-furosemide","drug-amlodipine","drug-lisinopril","drug-hctz"]}'::jsonb),
('dis-002', 'disease', 'type-2-diabetes', 'zh-TW', 'published', '{"id":"dis-002","type":"disease","slug":"type-2-diabetes","locale":"zh-TW","title":"第 2 型糖尿病 (Type 2 DM)","subtitle":"T2DM · 慢性代謝疾病","aliases":["T2DM","糖尿病","type 2 diabetes","diabetes mellitus"],"shortSummary":"長期高血糖造成多系統慢性傷害；血糖目標個別化，急性高低血糖為護理重點。","targetUser":["nursing_student"],"clinicalSetting":["ward","opd","community"],"ageScope":["adult","elderly"],"priority":"high","tags":["endocrine","常見疾病"],"categories":["疾病/內分泌/糖尿病"],"caution":[{"level":"warning","message":"本卡為學習用一般知識，不可作為個別病人之診斷或治療依據。"}],"redFlags":[{"trigger":"意識變化伴隨血糖 < 70 mg/dL 或 > 300 mg/dL","actionHint":"考慮通報並依單位低血糖 / 高血糖緊急規範跟進。"}],"bodySections":[{"key":"symptoms","label":"常見表現","layout":"bullet","collapsedByDefault":false,"displayHint":"front","content":["多尿、多渴、多食","體重減輕","疲倦、傷口癒合差","視力模糊"]}],"quickActions":[],"references":[{"citation":"一般護理基礎教科書（範例條目）","sourceType":"textbook","sourceLang":"zh-TW"}],"review":{"version":"1.0.0","authoredBy":["seed"],"reviewedBy":[],"nextReviewDue":"2027-01-01","approvalScopes":["clinical_accuracy"]},"status":"published","createdAt":"2026-01-01T00:00:00Z","updatedAt":"2026-04-01T00:00:00Z","searchKeywords":["T2DM","糖尿病","diabetes"],"icd10":["E11"],"oneLinerDefinition":"胰島素分泌與作用不足造成慢性高血糖的代謝疾病。","pathophysiologyBrief":"初期胰島素阻抗為主，β 細胞代償性增加分泌；長期下來分泌功能下降造成持續高血糖，長期影響微血管與大血管。","typicalPresentation":["多尿 / 多渴 / 多食","體重減輕","視力模糊","傷口癒合不良"],"keyInvestigations":["空腹血糖","HbA1c","OGTT","尿微量白蛋白"],"treatmentOverview":"治療概念包括生活型態介入（飲食、運動、體重）、口服降血糖藥（如 Metformin、SGLT2i、DPP-4i、GLP-1RA 等類別）以及胰島素治療。個別處方以主治醫師判斷為準。","nursingPriorities":[{"priority":"critical","point":"低血糖辨識與處置（依單位規範）","rationale":"冒冷汗、心悸、意識變化等需立刻處置。"},{"priority":"high","point":"飲食、運動、用藥順從性衛教"},{"priority":"high","point":"足部照護與末梢循環評估"},{"priority":"normal","point":"長期目標：HbA1c、血壓、血脂個別化目標"}],"complications":["視網膜病變","腎病變","神經病變","心血管事件","足部潰瘍"],"relatedDrugIds":["drug-metformin","drug-glimepiride","drug-insulin"]}'::jsonb),
('edu-001', 'health_edu', 'hypertension-education', 'zh-TW', 'published', '{"id":"edu-001","type":"health_edu","slug":"hypertension-education","locale":"zh-TW","title":"高血壓衛教","subtitle":"日常自我管理重點","aliases":["HTN 衛教","高血壓教育","hypertension education"],"shortSummary":"高血壓病人日常飲食、運動、用藥與居家量血壓的核心衛教重點，搭配 30 秒口語版腳本。","targetUser":["nursing_student"],"clinicalSetting":["ward","opd","community","home"],"ageScope":["adult","elderly"],"priority":"normal","tags":["衛教","cardiovascular"],"categories":["衛教/心血管/高血壓"],"caution":[{"level":"warning","message":"進行衛教前請先與帶教老師或醫療團隊確認本案個別差異與醫囑內容。"}],"bodySections":[{"key":"do_and_dont","label":"建議與避免","layout":"comparison","collapsedByDefault":false,"displayHint":"front","content":[{"label":"建議","bullets":["低鈉飲食（鹽分減量、避免醃漬與加工食品）","每週至少 150 分鐘中強度有氧運動（依醫師建議）","居家固定時段量血壓並紀錄","規律睡眠、適度紓壓"]},{"label":"避免","bullets":["突然停藥（包括症狀好轉時）","過量咖啡因、酒精","吸菸","私自合併使用止痛藥（NSAIDs）"]}]},{"key":"misconception","label":"常見誤解","layout":"bullet","collapsedByDefault":true,"displayHint":"expanded","content":["「血壓正常就可以停藥」— 多數需要長期控制，停藥前須先諮詢醫師。","「沒有頭痛就沒事」— 高血壓多無症狀，仍會傷害心、腦、腎。","「血壓越低越好」— 過低反而會頭暈與跌倒。"]}],"quickActions":[{"type":"copy_text","label":"複製 30 秒口語版"}],"references":[{"citation":"一般病人衛教手冊（範例條目）","sourceType":"institutional_sop","sourceLang":"zh-TW"}],"review":{"version":"1.0.0","authoredBy":["seed"],"reviewedBy":[],"nextReviewDue":"2027-01-01","approvalScopes":["clinical_accuracy","language"]},"status":"published","createdAt":"2026-01-01T00:00:00Z","updatedAt":"2026-04-01T00:00:00Z","searchKeywords":["高血壓衛教","HTN","衛教","低鈉"],"topic":"高血壓","targetPatient":["adult","elderly","caregiver"],"readingLevel":"low","keyMessages":["高血壓需要長期管理，不能因為沒症狀就停藥。","飲食上以「少鈉、多蔬果、控制體重」為原則。","每天固定時段量血壓並紀錄，回診時帶給醫師看。","出現嚴重頭痛、胸痛、視力模糊或意識變化，請盡快回院。"],"explainIn30s":"高血壓是長期的問題，多數時候不會有感覺，但會慢慢傷到心臟、腦、腎臟。請固定吃藥、減少鹽分、規律運動，每天量血壓並紀錄；如果出現嚴重頭痛、胸痛或意識變化，請盡快回院。以上是一般衛教重點，您的醫師會依您個別狀況調整。","teachBackQuestions":["今天量血壓的目標時間是什麼時候？","高血壓的飲食原則中，最重要的一項是？","如果出現哪些症狀需要立刻回院？"],"commonMisconceptions":["血壓正常就可以停藥","沒症狀就代表控制得很好","血壓降得越低越好"],"doAndDont":{"do":["低鈉飲食","規律運動","居家固定量血壓","規律服藥","規律睡眠"],"dont":["自行停藥","過量咖啡因 / 酒精","吸菸","私自合併 NSAIDs"]},"relatedDiseaseIds":["dis-001"]}'::jsonb),
('edu-002', 'health_edu', 'hypotension-education', 'zh-TW', 'published', '{"id":"edu-002","type":"health_edu","slug":"hypotension-education","locale":"zh-TW","title":"低血壓衛教","subtitle":"預防跌倒與症狀辨識","aliases":["HoTN 衛教","低血壓教育","hypotension education"],"shortSummary":"低血壓病人之症狀辨識、姿勢性低血壓預防、跌倒安全與何時回診之核心衛教。","targetUser":["nursing_student"],"clinicalSetting":["ward","opd","community","home"],"ageScope":["adult","elderly"],"priority":"normal","tags":["衛教","cardiovascular"],"categories":["衛教/心血管/低血壓"],"caution":[{"level":"warning","message":"進行衛教前請先與帶教老師或醫療團隊確認本案個別差異與醫囑內容。"}],"bodySections":[{"key":"do_and_dont","label":"建議與避免","layout":"comparison","collapsedByDefault":false,"displayHint":"front","content":[{"label":"建議","bullets":["起立前先在床邊坐 1–2 分鐘再站起","充足水分攝取（依醫囑限制者除外）","少量多餐避免飯後低血壓","量血壓並紀錄起立前後的差異"]},{"label":"避免","bullets":["快速從躺姿改變為站姿","長時間直立 / 站立工作未休息","高溫環境長時間活動","突然停降壓藥（需先與醫師討論）"]}]}],"quickActions":[{"type":"copy_text","label":"複製 30 秒口語版"}],"references":[{"citation":"一般病人衛教手冊（範例條目）","sourceType":"institutional_sop","sourceLang":"zh-TW"}],"review":{"version":"1.0.0","authoredBy":["seed"],"reviewedBy":[],"nextReviewDue":"2027-01-01","approvalScopes":["clinical_accuracy","language"]},"status":"published","createdAt":"2026-01-01T00:00:00Z","updatedAt":"2026-04-01T00:00:00Z","searchKeywords":["低血壓衛教","HoTN","姿勢性低血壓","跌倒"],"topic":"低血壓","targetPatient":["adult","elderly","caregiver"],"readingLevel":"low","keyMessages":["低血壓常在起立時造成頭暈，請慢慢改變姿勢。","出現眼前發黑、嚴重頭暈、跌倒、意識不清，請盡快回院。","若服用降壓藥，請與醫師討論是否需要調整。"],"explainIn30s":"低血壓常常在站起來的時候造成頭暈，建議起床前先在床邊坐 1–2 分鐘再慢慢站起。日常多補充水分、少量多餐，避免長時間站立或熱環境。如果出現眼前發黑、嚴重頭暈、跌倒或意識變化，請盡快回院。以上是一般衛教重點，您的醫師會依您個別狀況調整。","teachBackQuestions":["為什麼起立前要先坐一下？","出現哪些症狀需要回院？"],"doAndDont":{"do":["起立動作放慢","充足水分","少量多餐","記錄頭暈發生時機"],"dont":["快速起立","高溫環境長時間活動","自行停藥"]}}'::jsonb),
('isbar-001', 'isbar', 'deterioration-report', 'zh-TW', 'published', '{"id":"isbar-001","type":"isbar","slug":"deterioration-report","locale":"zh-TW","title":"ISBAR — 病情變化通報","subtitle":"Deterioration scenario","aliases":["ISBAR 通報","病情變化","deterioration"],"shortSummary":"當病人出現病情變化（生命徵象異常、意識變化等）時，組織通報內容的 ISBAR 模板。","targetUser":["nursing_student"],"clinicalSetting":["ward","icu","er"],"priority":"high","tags":["ISBAR","溝通","病情變化"],"categories":["溝通/ISBAR"],"caution":[{"level":"critical","message":"請勿輸入可辨識病人資料（姓名、病歷號、身分證、聯絡方式）。離開實習單位前請確認清空。"}],"bodySections":[{"key":"pitfalls","label":"常見陷阱","layout":"bullet","collapsedByDefault":false,"displayHint":"expanded","content":["只說「病人不舒服」不夠 — 用具體數值。","請先呼叫支援 / 通報，再開始填表整理。","不要在自由欄位輸入可辨識病人資料。"]}],"quickActions":[{"type":"copy_text","label":"複製通報文字塊"}],"references":[{"citation":"一般 ISBAR 教學素材（範例條目）","sourceType":"institutional_sop","sourceLang":"zh-TW"}],"review":{"version":"1.0.0","authoredBy":["seed"],"reviewedBy":[],"nextReviewDue":"2027-01-01","approvalScopes":["safety_disclaimer","language"]},"status":"published","createdAt":"2026-01-01T00:00:00Z","updatedAt":"2026-04-01T00:00:00Z","searchKeywords":["ISBAR","交班","通報","handover"],"scenario":"deterioration","fieldsSchema":{"I_identify":[{"key":"reporter_role","label":"報告者角色","type":"text","required":true,"hint":"例：實習護生 / 病房 N1","validators":["no_pii","max_length_120"]},{"key":"ward","label":"單位 / 床號","type":"text","required":true,"hint":"例：3A 病房 / 床號","validators":["no_pii","max_length_120"]}],"S_situation":[{"key":"situation","label":"目前狀況","type":"multiline","required":true,"hint":"一句話描述目前發生什麼事","validators":["no_pii","max_length_500"]},{"key":"vital_signs","label":"目前生命徵象","type":"text","required":false,"hint":"BP / HR / RR / Temp / SpO2","validators":["no_pii","max_length_120"]}],"B_background":[{"key":"background","label":"病情背景 / 主診斷","type":"multiline","required":false,"hint":"簡述主診斷與相關背景；勿輸入可辨識資料","validators":["no_pii","max_length_500"]},{"key":"allergy","label":"已知過敏","type":"text","required":false,"validators":["no_pii","max_length_120"]}],"A_assessment":[{"key":"assessment","label":"我的評估","type":"multiline","required":true,"hint":"你「覺得」可能是什麼問題？方向式語言","validators":["no_pii","max_length_500"]}],"R_recommendation":[{"key":"recommendation","label":"建議方向 / 需要的協助","type":"multiline","required":true,"hint":"例：希望您過來看 / 是否考慮抽 BCP / 是否考慮 NPO","validators":["no_pii","max_length_500"]}]},"exampleFilled":{"values":{"reporter_role":"實習護生（指導者：林護理師）","ward":"3A / 床 12","situation":"病人近 30 分鐘 BP 由 130/80 降至 92/55，主訴頭暈伴隨冒冷汗。","vital_signs":"BP 92/55, HR 112, RR 22, SpO2 95% on RA, Temp 36.8°C","background":"50 多歲男性，主診斷 CHF；今晨給予 Furosemide 40 mg PO。","allergy":"NKDA","assessment":"可能與利尿後容量不足 / 姿勢性低血壓相關，意識清楚但虛弱。","recommendation":"已平躺、抬腳；請問是否考慮 IV 補液與重抽電解質？"},"renderedOutput":"I: 實習護生（指導者：林護理師），3A / 床 12\nS: 病人近 30 分鐘 BP 由 130/80 降至 92/55，主訴頭暈伴隨冒冷汗。生命徵象：BP 92/55, HR 112, RR 22, SpO2 95% on RA, Temp 36.8°C\nB: 50 多歲男性，主診斷 CHF；今晨給予 Furosemide 40 mg PO。已知過敏：NKDA\nA: 可能與利尿後容量不足 / 姿勢性低血壓相關，意識清楚但虛弱。\nR: 已平躺、抬腳；請問是否考慮 IV 補液與重抽電解質？"},"outputTemplate":"I: {{reporter_role}}，{{ward}}\nS: {{situation}}{{#vital_signs}}\n生命徵象：{{vital_signs}}{{/vital_signs}}\nB: {{background}}{{#allergy}}\n已知過敏：{{allergy}}{{/allergy}}\nA: {{assessment}}\nR: {{recommendation}}","pitfalls":["不要在自由欄位輸入病人姓名、病歷號、身分證、電話。","請先呼叫支援 / 通報，再開始填表整理。","避免使用「立即…」「應該…」等絕對指令；建議方向式語言。"],"privacyRules":{"blockPii":true,"blockedFields":["situation","background","assessment","recommendation"],"autoClearAfter":"session_end"}}'::jsonb),
('med-001', 'med_safety', 'three-reads-six-rights', 'zh-TW', 'published', '{"id":"med-001","type":"med_safety","slug":"three-reads-six-rights","locale":"zh-TW","title":"給藥三讀六對","subtitle":"MVP 安全爆點 — 給藥前 30 秒輔助核對","aliases":["三讀六對","給藥核對","medication check","六大對"],"shortSummary":"給藥前的輔助再核對流程，輔助臨床的「三讀六對」原則；本流程不取代法定核對與單位規範。","targetUser":["nursing_student"],"clinicalSetting":["ward","icu","er","pediatric"],"priority":"critical","tags":["安全","給藥","MedCheck"],"categories":["安全/給藥核對"],"caution":[{"level":"critical","message":"本核對流程為輔助再核對，不取代法定三讀六對。最終給藥責任仍在您與監督您的護理人員。任一步驟有疑慮即停止並通報。"}],"redFlags":[{"trigger":"病人辨識資訊與藥袋對不上","actionHint":"停止給藥，向護理人員 / 帶教老師回報並依單位規範處理。"},{"trigger":"藥物與最新醫囑（劑量 / 頻次 / 途徑）對不上","actionHint":"停止給藥，先核對處方來源，必要時聯繫開立醫師。"},{"trigger":"病人對該藥物有已知過敏史或近期發生新副作用","actionHint":"停止給藥，回報並依單位過敏處置規範跟進。"}],"bodySections":[{"key":"flow_note","label":"使用方式","layout":"paragraph","collapsedByDefault":false,"displayHint":"expanded","content":"本流程分為「準備期 → 床邊核對 → 給藥後紀錄」三段，每段以勾選方式完成。若任一步驟對不上，App 會引導至「停止並通報」頁面，並記錄一次本班的攔截事件（不含病人資料）。"}],"quickActions":[{"type":"open_checklist","label":"開始三讀六對"}],"references":[{"citation":"一般護理基礎教科書 — 給藥安全（範例條目）","sourceType":"textbook","sourceLang":"zh-TW"},{"citation":"院內給藥 SOP（範例條目）","sourceType":"institutional_sop","sourceLang":"zh-TW"}],"review":{"version":"1.0.0","authoredBy":["seed"],"reviewedBy":[],"nextReviewDue":"2026-12-01","approvalScopes":["clinical_accuracy","safety_disclaimer","language"]},"status":"published","createdAt":"2026-01-01T00:00:00Z","updatedAt":"2026-04-01T00:00:00Z","searchKeywords":["三讀六對","給藥核對","med check","六大對"],"checkType":"6_rights","appliesToRoutes":["po","iv","im","sc","sl","inhaled","topical","pr"],"requiresSecondVerifier":false,"timeoutRequired":false,"abortConditions":[{"trigger":"病人身分與藥袋資訊不一致","actionHint":"停止給藥並依單位規範回報。"},{"trigger":"藥物與最新醫囑不一致（劑量 / 頻次 / 途徑）","actionHint":"停止給藥並核對處方來源。"},{"trigger":"病人對該藥物有已知過敏 / 近期新增副作用","actionHint":"停止給藥並依單位過敏處置規範處理。"},{"trigger":"對任何一步有疑慮或不確定","actionHint":"停止流程並請教護理人員 / 帶教老師。"}],"preCheckSteps":[{"index":1,"text":"查對最新醫囑（病人、藥物、劑量、途徑、頻次、時間）。","mustConfirm":true,"guidance":"紙本或電子醫囑皆以「最新版本」為準。"},{"index":2,"text":"查對藥袋 / 藥盒標籤（取藥時的「第一讀」）。","mustConfirm":true},{"index":3,"text":"檢查過敏史、最近副作用、相關生命徵象 / 檢驗值。","mustConfirm":true}],"bedsideSteps":[{"index":4,"text":"床邊辨識病人（依單位規範使用兩項辨識；勿只看床號）。","mustConfirm":true},{"index":5,"text":"再次比對藥袋（「第二讀」）：病人、藥物、劑量、途徑、頻次、時間。","mustConfirm":true},{"index":6,"text":"說明給藥目的並取得病人理解 / 同意。","mustConfirm":true},{"index":7,"text":"給藥前的最後一讀（「第三讀」）— 倒藥 / 抽藥當下再確認。","mustConfirm":true}],"postAdminSteps":[{"index":8,"text":"完成給藥紀錄（時間、劑量、途徑、反應）。","mustConfirm":true},{"index":9,"text":"依藥物與單位規範安排後續觀察（生命徵象、副作用）。","mustConfirm":true}],"documentationRequired":["給藥時間、劑量、途徑、執行者","病人即時反應與必要的觀察值","若有中止，記錄中止原因與通報對象"],"auditTrail":{"logCompletion":true,"logPii":false,"retention":"shift"}}'::jsonb)
